insert into public.courses
    (code, name, hours, description, exclusions, breadth, prereq_tree)
values
    ('SPA490H1', 'Independent Studies in Spanish', null, 'A unique opportunity for students interested in pursuing an in-depth study on a specific topic related to Spanish Studies, but beyond the scope of regular course offerings. The student, aided and advised by a faculty member in the Spanish program acting as supervisor, will produce a substantive written report on original and independent investigation of an appropriate topic. Students interested must contact the Associate Chair of Undergraduate Studies to learn about the process and request an application form. More details available in our website: https://www.spanport.utoronto.ca/ . Deadline for submission of application form is five business days before the first day of classes of the session in which student wishes to enroll in the course. Not elegible for CR/NCR.', null, null, '{"operator": "AND", "items": [{"credits": 0.5, "department": "SPA"}]}'::jsonb),
    ('SPA491H1', 'Independent Studies in Spanish', null, 'A unique opportunity for students interested in pursuing an in-depth study on a specific topic related to Spanish Studies, but beyond the scope of regular course offerings. The student, aided and advised by a faculty member in the Spanish program acting as supervisor, will produce a substantive written report on original and independent investigation of an appropriate topic. Students interested must contact the Associate Chair of Undergraduate Studies to learn about the process and request an application form. More details available in our website: https://www.spanport.utoronto.ca/. Deadline for submission of application form is five business days before the first day of classes of the session in which student wishes to enroll in the course. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 0.5, "department": "SPA"}]}'::jsonb),
    ('STA130H1', 'An Introduction to Statistical Reasoning and Data Science', '24L/24P', 'This course, intended for students considering a program in Statistical Sciences, discusses the crucial role played by statistical reasoning in solving challenging problems from natural science, social science, technology, health care, and public policy, using a combination of logical thinking, mathematics, computer simulation, and oral and written discussion and analysis.', 'Any of  STA220H1/  STA255H1/  STA238H1/  STA248H1/  STA261H1/  ECO220Y1/  ECO227Y1/  STAB22H3/  STA220H5/  STAB57H3/  STA258H5/  STA260H5/  ECO220Y5/  ECO227Y5/  STAA57H3 taken previously or concurrently', 5, null::jsonb),
    ('STA197H1', 'Thinking Better with Statistics', '24S', 'This course explores how our statistical intuitions and ways of thinking can let us down. There''s no need to be a math whiz to be a better statistical thinker. Everyone can become a more critical consumer of claims presented in media, advertisements and by politicians—especially those relevant to our own health and wealth. This course uses real-world examples and tours common and avoidable statistical traps and tricks. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('STA198H1', 'Probabilities Everywhere', '24S', 'This course examines the meaning and mathematics of probabilities, and how they arise in our everyday lives. Specific topics may include: the nature of coincidences, the concept of luck, games involving dice and cards, long run averages in casinos, margins of error in polls, the interpretation of medical studies, crime statistics, decision making, pseudorandomness, and Monte Carlo algorithms. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('STA199H1', 'Statistical Evidence: Truth or Myth?', '24S', 'This course explores the impact Statistics has made and continues to make on everyday life through science, law, and the modern methods for information processing. Statistical principles will be illustrated using examples from real life including business, romance and health. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('STA201H1', 'Why Numbers Matter', '36L', 'This course teaches non-science students the importance of quantitative reasoning to many different areas. It explores a variety of applications to such diverse subjects as economics, gambling, politics, poetry, graphics, music, medicine, demographics, sports, secret codes, and more, using only basic high school level mathematics combined with logical thinking.', 'MAT133Y1/ MAT135H1/ MAT136H1/ MAT137Y1/ MAT157Y1/( MATA29H3,  MATA35H3)/( MATA32H3,  MATA33H3)/( MATA30H3,  MATA36H3)/( MATA31H3,  MATA37H3)/ MAT133Y5/( MAT132H5, MAT134H5)/( MAT135H5, MAT136H5)/ MAT137Y5/ MAT157Y5', 5, null::jsonb),
    ('STA220H1', 'The Practice of Statistics I', '36L', 'An introductory course in statistical concepts and methods, emphasizing exploratory data analysis for univariate and bivariate data, sampling and experimental designs, basic probability models, estimation and tests of hypothesis in one-sample and comparative two-sample studies. A statistical computing package is used but no prior computing experience is assumed. Note:  STA220H1 does not count as a distribution requirement course.', 'ECO220Y1/  ECO227Y1/  GGR270H1/  IRW220H1/  PSY201H1/  SOC202H1/  STA261H1/  STA238H1/  STA248H1/  STA288H1/  EEB225H1/  STAB22H3/  STAB57H3/  STA215H5/  STA220H5/  ECO220Y5/  ECO227Y5/  STA258H5/  STA260H5', 5, null::jsonb),
    ('STA221H1', 'The Practice of Statistics II', '36L/12T', 'Continuation of  STA220H1 (or similar course), emphasizing major methods of data analysis such as analysis of variance for one factor and multiple factor designs, regression models, categorical and non-parametric methods (Note:  STA221H1 does not count as a distribution requirement course).', 'ECO220Y1/  ECO227Y1/  GGR270Y1/  PSY202H1/  SOC202H1/  SOC252H1/  STA261H1/  STA248H1/  STAB27H3/  STA221H5/  ECO220Y5/  ECO227Y5/  STAB57H3/  STA258H5/  STA260H5', 5, '{"operator": "OR", "items": ["STA220H1", "STA288H1", "PSY201H1", "GGR270H1", "EEB225H1", "STAB22H3", "STA220H5"]}'::jsonb),
    ('STA237H1', 'Probability, Statistics and Data Analysis I', '36L/12T', 'An introduction to probability using simulation and mathematical frameworks, with emphasis on the probability needed for more advanced study in statistical practice. Topics covered include probability spaces, random variables, discrete and continuous probability distributions, probability mass, density, and distribution functions, expectation and variance, independence, conditional probability, the law of large numbers, the central limit theorem, sampling distributions. Computer simulation will be taught and used extensively for calculations and to guide the theoretical development.', 'STA247H1,  STA201H1,  STA255H1,  STA257H1,  ECO227Y1,  MAT370H1,  STAB52H3,  STA256H5,  ECO227Y5', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1", {"operator": "AND", "items": ["MATA30H3", "MATA36H3"]}, {"operator": "AND", "items": ["MATA31H3", "MATA37H3"]}, {"operator": "AND", "items": ["MAT135H5", "MAT136H5"]}, "MAT137Y5", "MAT157Y5", {"operator": "AND", "items": ["MAT137H5", "MAT139H5"]}, {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}]}'::jsonb),
    ('STA238H1', 'Probability, Statistics and Data Analysis II', '36L/12T', 'An introduction to statistical inference and practice. Statistical models and parameters, estimators of parameters and their statistical properties, methods of estimation, confidence intervals, hypothesis testing, likelihood function, the linear model. Use of statistical computation for data analysis and simulation.', 'ECO220Y1/  ECO227Y1/  GGR270H1/  PSY201H1/  SOC300H1/  SOC202H1/  SOC252H1/  STA220H1/  STA221H1/  STA255H1/  STA248H1/  STA261H1/  STA288H1/  EEB225H1/  STAB22H3/  STAB27H3/  STAB57H3/  STA220H5/  STA221H5/  STA258H5/  STA260H5/  ECO220Y5/  ECO227Y5', 5, '{"operator": "OR", "items": ["STA237H1", "STA247H1", "STA257H1", "STAB52H3", "STA256H5"]}'::jsonb),
    ('STA247H1', 'Probability with Computer Applications', '36L/12T', 'An introduction to probability using simulation and mathematical frameworks, with emphasis on the probability needed for computer science applications and more advanced study in statistical practice. Topics covered include probability spaces, random variables, discrete and continuous probability distributions, probability mass, density, and distribution functions, expectation and variance, independence, conditional probability, the law of large numbers, the central limit theorem, sampling distributions. Computer simulation will be taught and used extensively for calculations and to guide the theoretical development.', 'ECO227Y1/  STA201H1/  STA237H1/  STA255H1/  STA257H1/  STAB52H3/  STA256H5/  ECO227Y5', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1", {"operator": "AND", "items": ["MATA30H3", "MATA36H3"]}, {"operator": "AND", "items": ["MATA31H3", "MATA37H3"]}, {"operator": "AND", "items": ["MAT135H5", "MAT136H5"]}, "MAT137Y5", {"operator": "AND", "items": ["MAT137H5", "MAT139H5"]}, "MAT157Y5", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}]}, {"operator": "OR", "items": ["CSC111H1", "CSC148H1", "CSCA48H3", "CSC148H5"]}]}'::jsonb),
    ('STA248H1', 'Statistics for Computer Scientists', '36L/12T', 'An introduction to statistical inference and practice needed for computer science applications. Statistical models and parameters, estimators of parameters and their statistical properties, methods of estimation, confidence intervals, hypothesis testing, likelihood function, the linear model. Use of statistical computation for data analysis and simulation.', 'ECO220Y1/  ECO227Y1/  GGR270H1/  PSY201H1/  SOC300H1/  SOC202H1/  SOC252H1/  STA220H1/  STA221H1/  STA255H1/  STA238H1/  STA261H1/  STA288H1/  EEB225H1/  STAB22H3/  STAB27H3/  STAB57H3/  STA220H5/  STA221H5/  STA258H5/  STA260H5/  ECO220Y5/  ECO227Y5', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["STA237H1", "STA247H1", "STA257H1", "STA256H5", "STAB52H3"]}, {"operator": "OR", "items": ["CSC111H1", "CSC148H1", "CSCA48H3", "CSC148H5"]}]}'::jsonb),
    ('STA255H1', 'Statistical Theory', '36L/12T', 'This courses deals with the mathematical aspects of some of the topics discussed in  STA220H1. Topics include discrete and continuous probability distributions, conditional probability, expectation, sampling distributions, estimation and testing, the linear model (Note:  STA255H1 does not count as a distribution requirement course).', 'ECO227Y1/  STA201H1/  STA237H1/  STA238H1/  STA257H1/  STA261H1/  STA247H1/  STA248H1/  STAB52H3/  STAB57H3/  STA256H5/  STA260H5', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["STA220H1", "STA221H1", "STA288H1", "ECO220Y1", "STAB22H3", "STA220H5", "ECO220Y5"]}, {"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1", {"operator": "AND", "items": ["MATA32H3", "MATA33H3"]}, {"operator": "AND", "items": ["MATA29H3", "MATA35H3"]}, {"operator": "AND", "items": ["MATA30H3", "MATA36H3"]}, {"operator": "AND", "items": ["MATA31H3", "MATA37H3"]}, "MAT133Y5", {"operator": "AND", "items": ["MAT132H5", "MAT134H5"]}, {"operator": "AND", "items": ["MAT135H5", "MAT136H5"]}, "MAT137Y5", "MAT157Y5", {"operator": "AND", "items": ["MAT137H5", "MAT139H5"]}, {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}]}]}'::jsonb),
    ('STA257H1', 'Probability and Statistics I', '36L/12T', 'A mathematically rigorous introduction to probability, with applications chosen to introduce concepts of statistical inference. Probability and expectation, discrete and continuous random variables and vectors, distribution and density functions, the law of large numbers. The binomial, geometric, Poisson, and normal distributions. The Central Limit Theorem. (Note:  STA257H1 does not count as a distribution requirement course).', 'ECO227Y1,  STA201H1,  STA237H1,  STA247H1,  MAT370H1,  MAT377H1,  STAB52H3,  STA256H5,  ECO227Y5', 5, '{"operator": "OR", "items": ["MAT137Y1", "MAT157Y1", {"operator": "AND", "items": ["MATA31H3", "MATA37H3"]}, "MAT137Y5", "MAT157Y5", {"operator": "AND", "items": ["MAT137H5", "MAT139H5"]}, {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}]}'::jsonb),
    ('STA261H1', 'Probability and Statistics II', '36L/12T', 'A rigorous introduction to the theory of statistical inference and to statistical practice. Statistical models, parameters, and samples. Estimators for parameters, sampling distributions for estimators, and the properties of consistency, bias, and variance. The likelihood function and the maximum likelihood estimator. Hypothesis tests and confidence regions. Examples illustrating statistical theory and its limitations. Introduction to the use of a computer environment for statistical analysis. (Note:  STA261H1 does not count as a distribution requirement course).', 'ECO227Y1/  STA238H1/  STA248H1/  STAB57H3/  STA260H5/  ECO227Y5', 5, '{"operator": "OR", "items": ["STA257H1", "STAB52H3", "STA256H5"]}'::jsonb),
    ('STA272H1', 'Statistical Models for Data Science', '24L/12T', 'Key areas of data science modeling including question formulation, data collection and cleaning, visualization, statistical inference, predictive modeling, and decision making.​ Through a strong emphasis on data-centric computing, quantitative critical thinking, and exploratory data analysis, this class covers key principles and techniques of data science. These include algorithms for statistical models and machine learning methods including regression, classification, neural networks, and clustering; principles behind creating informative data visualizations; and statistical concepts of measurement error and prediction.', 'Any 300+ level STA course,  CSC311H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC108H1", "CSC110Y1", "CSC148H1"]}, {"operator": "OR", "items": ["STA220H1", "ECO220Y1", "ECO227Y1", "GGR270H1", "IRW220H1", "PSY201H1", "STA261H1", "STA238H1", "STA248H1", "STA288H1", "EEB225H1"]}]}'::jsonb),
    ('STA288H1', 'Statistics and Scientific Inquiry in the Life Sciences', '36L/18P', 'Introduction to statistics and its connection to all stages of the scientific inquiry process. Issues around data collection, analysis and interpretation are emphasized to inform study design and critical assessment of published research. Statistical software is used to conduct descriptive and inferential statistics to address basic life sciences research questions.', 'STA220H1,  PSY201H1,  GGR270H1,  ECO220Y1,  ECO227Y1,  SOC202H1,  EEB225H1,  HMB325H1,  STA238H1,  STA248H1,  STA261H1,  PCL376H1,  STA215H5,  STA220H5,  STAB22H3', 5, '{"operator": "AND", "items": ["BIO120H1", "BIO130H1"]}'::jsonb),
    ('STA299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('STA299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('STA302H1', 'Methods of Data Analysis I', '36L', 'Introduction to data analysis with a focus on regression. Initial Examination of data. Correlation. Simple and multiple regression models using least squares. Inference for regression parameters, confidence and prediction intervals. Diagnostics and remedial measures. Interactions and dummy variables. Variable selection. Least squares estimation and inference for non-linear regression.', 'STAC67H3,  STA302H5', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["STA238H1", "STA248H1", "STA255H1", "STA261H1", "ECO227Y1", "STAB57H3", "STA258H5", "STA260H5", "ECO227Y5"]}, {"operator": "OR", "items": ["CSC108H1", "CSC110Y1", "CSC120H1", "CSC148H1", "CSCA08H3", "CSCA20H3", "CSCA48H3", "CSC108H5", "CSC148H5"]}, {"operator": "OR", "items": ["MAT223H1", "MAT224H1", "MAT240H1", "MATA22H3", "MATA23H3", "MAT223H5", "MAT240H5", "MATB24H3", "MAT224H5"]}]}'::jsonb),
    ('STA303H1', 'Methods of Data Analysis II', '36L', 'Analysis of variance for one-and two-way layouts, logistic regression, loglinear models, longitudinal data, introduction to time series.', 'STAC51H3', 5, '{"operator": "OR", "items": ["STA302H1", "STAC67H3", "STA302H5"]}'::jsonb),
    ('STA304H1', 'Surveys, Sampling and Observational Data', '36L', 'Design of surveys, sources of bias, randomized response surveys. Techniques of sampling; stratification, clustering, unequal probability selection. Sampling inference, estimates of population mean and variances, ratio estimation. Observational data; correlation vs. causation, missing data, sources of bias.', 'STAC50H3,  STAC53H3,  STA304H5', 5, '{"operator": "OR", "items": ["ECO227Y1", "STA255H1", "STA261H1", "STA248H1", "STA238H1", "STAB57H3", "STA258H5", "STA260H5", "ECO227Y5"]}'::jsonb),
    ('STA305H1', 'Design and Analysis of Experiments', '36L', 'Experiments vs observational studies, experimental units. Designs with one source of variation. Complete randomized designs and randomized block designs. Factorial designs. Inferences for contrasts and means. Model assumptions. Crossed and nested treatment factors, random effects models. Analysis of variance and covariance. Sample size calculations.', 'STAC50H3,  STAC53H3,  STA305H5', 5, '{"operator": "OR", "items": ["STA302H1", "STAC67H3", "STA302H5"]}'::jsonb),
    ('STA313H1', 'Data Visualization', '24L/12P', 'An introduction to data visualization and the use of visual and interactive representations of data to support human cognition. This course covers visualization techniques and algorithms based on principles from graphic design, perceptual psychology, cognitive science, and human-computer interaction. Topics include: graphic design, interaction, perception and cognition, communication, and ethics. Computational tutorials involve design review, implementation, and testing of information visualizations.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC108H1", "CSC110Y1", "CSC120H1", "CSC148H1"]}, {"operator": "OR", "items": ["STA238H1", "STA248H1", "STA261H1", "ECO227Y1"]}]}'::jsonb),
    ('STA314H1', 'Statistical Methods for Machine Learning I', '36L/12T', 'Statistical methods for supervised and unsupervised learning from data: training error, test error and cross-validation; classification, regression, and logistic regression; principal components analysis; stochastic gradient descent; decision trees and random forests; k-means clustering and nearest neighbour methods. Computational tutorials will support the efficient application of these methods.', 'CSC311H1,  CSC311H5,  STA314H5,  STA315H5,  CSCC11H3', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["STA302H1", "STA302H5", "STAC67H3"]}, {"operator": "OR", "items": ["CSC108H1", "CSC110Y1", "CSC120H1", "CSC148H1", "CSCA08H3", "CSCA48H3", "CSCA20H3", "CSC108H5", "CSC148H5"]}, {"operator": "OR", "items": ["MAT223H1", "MAT224H1", "MAT240H1", "MATA22H3", "MATA23H3", "MAT223H5", "MAT240H5", "MATB24H3", "MAT224H5"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1", {"operator": "AND", "items": ["MATB41H3", "MATB42H3"]}, {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MAT233H5", "MAT236H5"]}]}]}'::jsonb),
    ('STA347H1', 'Probability', '36L', 'An overview of probability from a non-measure theoretic point of view. Random variables/vectors; independence, conditional expectation/probability and consequences. Various types of convergence leading to proofs of the major theorems in basic probability. An introduction to simple stochastic processes such as Poisson and branching processes.', 'MAT370H1,  MAT377H1,  STAC62H3,  STA348H5', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["STA247H1", "STA255H1", "STA237H1", "STA257H1", "ECO227Y1", "STAB52H3", "STA256H5"]}, {"operator": "OR", "items": ["MAT223H1", "MAT224H1", "MAT240H1", "MATA22H3", "MATA23H3", "MAT223H5", "MAT240H5", "MATB24H3", "MAT224H5"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1", {"operator": "AND", "items": ["MATB41H3", "MATB42H3"]}, {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MAT233H5", "MAT236H5"]}]}]}'::jsonb),
    ('STA355H1', 'Theory of Statistical Practice', '24L/12P', 'STA355H1 provides a unifying structure for the methods taught in other courses, and will enable students to read methodological research articles or articles with a large methodological component. Topics covered include statistical models and distributions; fundamentals of inference: estimation, hypothesis testing, and significance levels; likelihood functions and likelihood-based inference; prior distributions and Bayesian inference.', 'STAC58H3', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["STA255H1", "STA248H1", "STA238H1", "STA261H1", "ECO227Y1", "STAB57H3", "STA260H5", "ECO227Y5"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1", {"operator": "AND", "items": ["MATB41H3", "MATB42H3"]}, {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MAT233H5", "MAT236H5"]}]}, {"operator": "OR", "items": ["MAT223H1", "MAT224H1", "MAT240H1", "MATA22H3", "MATA23H3", "MAT223H5", "MAT240H5", "MATB24H3", "MAT224H5"]}]}'::jsonb),
    ('STA365H1', 'Applied Bayesian Statistics', '36L', 'Bayesian inference has become an important applied technique and is especially valued to solve complex problems. This course first examines the basics of Bayesian inference. From there, this course looks at modern, computational methods and how to make inferences on complex data problems.', null, 5, '{"operator": "OR", "items": ["STA302H1", "STAC67H3", "STA302H5"]}'::jsonb),
    ('STA398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('STA398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('STA399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('STA399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('STA410H1', 'Statistical Computation', '36L', 'Programming in an interactive statistical environment. Generating random variates and evaluating statistical methods by simulation. Algorithms for linear models, maximum likelihood estimation, and Bayesian inference. Statistical algorithms such as the Kalman filter and the EM algorithm. Graphical display of data.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["STA302H1", "STAC67H3", "STA302H5"]}, {"operator": "OR", "items": ["CSC110Y1", "CSC148H1", "CSCA48H3", "CSC148H5"]}, {"operator": "OR", "items": ["MAT223H1", "MAT224H1", "MAT240H1", "MATA22H3", "MATA23H3", "MAT223H5", "MAT240H5", "MATB24H3", "MAT224H5"]}]}'::jsonb),
    ('STA414H1', 'Statistical Methods for Machine Learning II', '36L', 'Probabilistic foundations of supervised and unsupervised learning methods such as naive Bayes, mixture models, and logistic regression. Gradient-based fitting of composite models including neural nets. Exact inference, stochastic variational inference, and Marko chain Monte Carlo. Variational autoencoders and generative adversarial networks.', 'CSC412H1,  STAD68H3', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["STA314H1", "CSC311H1", "CSC311H5", {"operator": "AND", "items": ["STA314H5", "STA315H5"]}, "CSCC11H3"]}, {"operator": "OR", "items": ["STA302H1", "STAC67H3", "STA302H5"]}, {"operator": "OR", "items": ["CSC108H1", "CSC110Y1", "CSC120H1", "CSC148H1", "CSCA08H3", "CSCA48H3", "CSCA20H3", "CSC108H5", "CSC148H5"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1", {"operator": "AND", "items": ["MATB41H3", "MATB42H3"]}, {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MAT233H5", "MAT236H5"]}]}, {"operator": "OR", "items": ["MAT223H1", "MAT224H1", "MAT240H1", "MATA22H3", "MATA23H3", "MAT223H5", "MAT240H5", "MATB24H3", "MAT224H5"]}]}'::jsonb),
    ('STA422H1', 'Theory of Statistical Inference', '36L', 'This course examines current theory of statistical inference, particularly likelihood-based methods and Bayesian methods with an emphasis on resolving present conflicts; log-model expansion and asymptotics are primary tools.', null, 5, '{"operator": "AND", "items": ["STA355H1"]}'::jsonb),
    ('STA437H1', 'Methods for Multivariate Data', '24L/12P', 'Practical techniques for the analysis of multivariate data; fundamental methods of data reduction with an introduction to underlying distribution theory; basic estimation and hypothesis testing for multivariate means and variances; regression coefficients; principal components and partial, multiple and canonical correlations; multivariate analysis of variance; profile analysis and curve fitting for repeated measurements; classification and the linear discriminant function.', 'STAD37H3,  STA437H5', 5, '{"operator": "OR", "items": ["STA302H1", "STAC67H3", "STA302H5"]}'::jsonb),
    ('STA442H1', 'Methods of Applied Statistics', '36L', 'Advanced topics in statistics and data analysis with emphasis on applications. Diagnostics and residuals in linear models, introduction to generalized linear models, graphical methods, additional topics such as random effects models, designed experiments, model selection, analysis of censored data, introduced as needed in the context of case studies.', 'STA441H5', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["STA303H1", {"operator": "AND", "items": ["STAC67H3", "STAC51H3"]}]}, {"operator": "OR", "items": ["CSC108H1", "CSC110Y1", "CSC120H1", "CSC148H1", "CSCA08H3", "CSCA48H3", "CSCA20H3", "CSC108H5", "CSC148H5"]}]}'::jsonb),
    ('STA447H1', 'Stochastic Processes', '36L', 'Discrete and continuous time processes with an emphasis on Markov, Gaussian and renewal processes. Martingales and further limit theorems. A variety of applications taken from some of the following areas are discussed in the context of stochastic modeling: Information Theory, Quantum Mechanics, Statistical Analyses of Stochastic Processes, Population Growth Models, Reliability, Queuing Models, Stochastic Calculus, Simulation (Monte Carlo Methods).', 'STA348H5, STAC63H5', 5, '{"operator": "OR", "items": ["STA347H1", "MAT377H1", "STAC62H3"]}'::jsonb),
    ('STA450H1', 'Topics in Statistics', '36L', 'Topics of current research interest are covered. Topics vary from year to year. As the necessary academic preparation for this course may vary from year to year, there may be additional prerequisites required, such as specific courses or an application to enrol. Students should contact the department at ug.statistics@utoronto.ca for information on this course, and enrolment in this course, for a given year.', null, 5, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('STA452H1', 'Mathematical Statistics I', '36L', 'Statistical theory and its applications at an advanced mathematical level. Topics include probability and distribution theory as it specifically pertains to the statistical analysis of data. Linear models and the geometry of data, least squares and the connection to conditional expectation. The basic concept of inference and the likelihood function.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT223H1", "MAT224H1", "MAT240H1", "MATA22H3", "MATA23H3", "MAT223H5", "MAT240H5", "MATB24H3", "MAT224H5"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1", {"operator": "AND", "items": ["MATB41H3", "MATB42H3"]}, {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MAT233H5", "MAT236H5"]}]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["STA257H1", "STA355H1"]}, "STA347H1"]}]}'::jsonb),
    ('STA453H1', 'Mathematical Statistics II', '36L', 'Continuation of  STA452H1: statistical theory and its applications at an advanced mathematical level. Topics include classical estimation, theory with methods based on the likelihood function and the likelihood statistics. Testing hypothesis and the evaluation of confidence from both a Bayesian and frequentist point of view.', null, 5, '{"operator": "AND", "items": ["STA452H1"]}'::jsonb),
    ('STA457H1', 'Time Series Analysis', '36L', 'An overview of methods and problems in the analysis of time series data. Topics include: descriptive methods, filtering and smoothing time series, theory of stationary processes, identification and estimation of time series models, forecasting, seasonal adjustment, spectral estimation, bivariate time series models.', 'STAD57H3,  STA457H5', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["STA302H1", "STAC67H3", "STA302H5"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1", {"operator": "AND", "items": ["MATB41H3", "MATB42H3"]}, {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MAT233H5", "MAT236H5"]}]}]}'::jsonb),
    ('STA465H1', 'Spatial Data Analysis', '36L', 'Data acquisition in the environmental, physical, and health sciences are increasingly spatial, and novel in the sense that specialized methods are required for analysis. This course will cover different types of spatial and spatiotemporal data and their analytic methods. Students will learn a variety of advanced techniques for analyzing geostatistical, areal, and point referenced data. Focus will be placed on visualizing spatial data, choosing the correct method for a specific research question, and communicating analytic results clearly and effectively.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["STA302H1", "STAC67H3", "STA302H5"]}, "STA303H1"]}'::jsonb),
    ('STA475H1', 'Survival Analysis', '36L', 'An overview of theory and methods in the analysis of survival data. Topics include survival distributions and their applications, parametric and non-parametric methods, proportional hazards regression, and extensions to competing risks and multistate modelling.', null, 5, null::jsonb),
    ('STA480H1', 'Fundamentals of Statistical Genetics', '36L/9P', 'Statistical analysis of genetic data is an important emerging research area with direct impact on population health. This course provides an introduction to the concepts and fundamentals of statistical genetics, including current research directions.  The course includes lectures and hands-on experience with R programming and state-of-the-art statistical genetics software packages.', null, 5, '{"operator": "AND", "items": ["STA303H1"]}'::jsonb),
    ('STA490Y1', 'Statistical Consultation, Communication, and Collaboration', '48L/48P', 'Through case studies and collaboration with researchers in other disciplines, students develop skills in the collaborative practice of Statistics. Focus is on pragmatic solutions to practical issues including study design, dealing with common complications in data analysis, and ethical practice, with particular emphasis on written communication. An application must be completed during the priority enrolment period the summer before the course is offered. Priority will be given to students who are completing all requirements of the Specialist in Statistical Science: Methods and Practice or the Applied Statistics Specialist that academic year. Space permitting, students in the Statistics Specialist, the Specialist in Statistical Science: Theory and Methods, the Data Science Specialist, or the Statistics Major will be considered for enrolment in the order in which they applied.', null, 5, '{"operator": "AND", "items": ["STA303H1", {"operator": "OR", "items": ["STA304H1", "STA305H1"]}]}'::jsonb),
    ('STA492H1', 'Seminar in Statistical Science', '36S', 'This course is intended for students completing the Statistical Science: Theory and Methods Specialist program. Novel influential ideas and current research topics in statistics will be explored through readings and discussion. Content will generally vary from semester to semester. Student presentations and written reports will be required.', null, 5, '{"operator": "AND", "items": ["STA355H1"]}'::jsonb),
    ('STA496H1', 'Readings in Statistics', null, 'Independent study under the direction of a Department of Statistical Sciences faculty member. There are a limited number of spaces in this course, and capacity varies from year to year based on the availability of faculty supervisors. Enrolment is subject to Department of Statistical Sciences and faculty supervisor approval. Students interested in this course should contact the department at ug.statistics@utoronto.ca for information on how to apply for enrolment in this course in a given year. Not eligible for CR/NCR option.', 'STA497H1/ STA498Y1/ STA499Y1', 5, '{"operator": "AND", "items": [{"credits": 1.0, "department": "STA"}]}'::jsonb),
    ('STA497H1', 'Readings in Statistics', null, 'Independent study under the direction of a Department of Statistical Sciences faculty member. There are a limited number of spaces in this course, and capacity varies from year to year based on the availability of faculty supervisors. Enrolment is subject to Department of Statistical Sciences and faculty supervisor approval. Students interested in this course should contact the department at ug.statistics@utoronto.ca for information on how to apply for enrolment in this course in a given year. Not eligible for CR/NCR option.', 'STA496H1/ STA498Y1/ STA499Y1', 5, '{"operator": "AND", "items": [{"credits": 1.0, "department": "STA"}]}'::jsonb),
    ('STA498Y1', 'Readings in Statistics', null, 'Independent study under the direction of a Department of Statistical Sciences faculty member. There are a limited number of spaces in this course, and capacity varies from year to year based on the availability of faculty supervisors. Enrolment is subject to Department of Statistical Sciences and faculty supervisor approval. Students interested in this course should contact the department at ug.statistics@utoronto.ca for information on how to apply for enrolment in this course in a given year. Not eligible for CR/NCR option.', 'STA496H1/ STA497H1/ STA499Y1', 5, '{"operator": "AND", "items": [{"credits": 1.0, "department": "STA"}]}'::jsonb),
    ('STA499Y1', 'Readings in Statistics', null, 'Independent study under the direction of a Department of Statistical Sciences faculty member. There are a limited number of spaces in this course, and capacity varies from year to year based on the availability of faculty supervisors. Enrolment is subject to Department of Statistical Sciences and faculty supervisor approval. Students interested in this course should contact the department at ug.statistics@utoronto.ca for information on how to apply for enrolment in this course in a given year. Not eligible for CR/NCR option.', 'STA496H1/ STA497H1/ STA498Y1', 5, '{"operator": "AND", "items": [{"credits": 1.0, "department": "STA"}]}'::jsonb),
    ('SWE100H1', 'Elementary Swedish I', '24L/24P', 'Elementary Swedish I gives students a basic knowledge of Swedish. Students learn to understand and use Swedish in everyday situations, and to read and write short texts on familiar themes, and speak about their immediate social environment and learn something about everyday life in both Finland and Sweden.', 'SWE101H1', 1, null::jsonb),
    ('SWE101H1', 'Elementary Swedish II', '24L/24P', 'Elementary Swedish II, a continuation of  SWE100H1 gives students a basic knowledge of Swedish. Students learn to understand and use Swedish in everyday situations, and to read and write short texts on familiar themes, and speak about their immediate social environment and learn something about everyday life in both Finland and Sweden.', null, 1, '{"operator": "OR", "items": ["SWE100H1"]}'::jsonb),
    ('TMU115H1', 'Musical Skills I & II', null, 'Reading and listening skills for diatonic and chromatic materials. Topics include sight singing, rhythm reading, keyboard harmony, and dictation.', null, null, null::jsonb),
    ('TMU140Y1', 'Music Theory I & II', null, 'Diatonic harmony, including principles of voice leading and harmonic progression. Chromatic harmony, including modulation, mixture, Neapolitan and augmented sixths. Course requirements include part-writing, analysis, and keyboard harmony/skills.', null, null, null::jsonb),
    ('TMU240Y1', 'Music Theory and Skills III & IV', null, 'The first semester focuses on the study of forms and analysis of repertoire from c.1700-c.1900; forms to be studied include binary, ternary, sonata, rondo, variation, and fugue. The second semester focuses on post-tonal theory and analysis of music post-1900 along with reading and listening skills suitable for understanding post-tonal music.', 'TMU230H1,  TMU231H1,  TMU232H1', null, '{"operator": "AND", "items": ["TMU115H1", "TMU140Y1"]}'::jsonb),
    ('TRN125Y1', 'Contemporary Issues in Health Science', '48S', 'Can the immune system be strengthened? Are some diseases incurable? What is the best way to stop the spread of a virus? This course examines the scientific principles underlying contemporary issues in the science of human health with the goal of exposing students to the current state of biomedical research. We will develop three distinct types of understanding that are essential to literacy about the science of human health: the basic concepts in science; the nature of scientific research; and the rules that govern how scientists do their work. This course will explore topics such as stem cells, gene editing, regenerative medicine, vaccination, drug development, and personalized medicine. Restricted to first-year students admitted to the Trinity One Program. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('TRN135Y1', 'Science and Social Choice', '48S', 'Many of the decisions we make as a society rely on advances in scientific knowledge. In this course, we will discuss a number of contemporary medical topics that involve complex scientific discoveries about health, the human body, disease, and infection. We will consider genes and study the medical implications of our growing understanding of the human genome. We will study a number of recent cases in order to explore how scientific findings influence decision-making in hospitals and the selection of social policies. We will also discuss the background forces that shape medical research and how this affects the kinds of health problems that are prioritized. The objective of this course is to develop a solid understanding of biological concepts related to human health and consider them in their wider social and ethical contexts. Restricted to first-year students admitted to the Trinity One Program. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('TRN136Y1', 'Canadian Health Policy in the Global Context', '48S', 'In this course we consider when our health policies support the highest standards of medical care, consistent with the latest discoveries in medical research. We examine the ways in which debates around ethics, effectiveness and efficiency shape global and national health policy. We begin by exploring the most important advancements in global health policy over the past two decades. We then assess Canada''s experience in providing health care, identifying lessons for national policy reform and for Canada''s role as a leader in global health research and policy. We explore a range of health challenges including universal health care, anti-microbial drug resistance, HIV AIDS, tuberculosis, reproductive, maternal, newborn and child health, cardiovascular care, oncology, environmental health, indigenous health, violence against women and mental health. Restricted to first-year students admitted to the Trinity One Program. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('TRN140Y1', 'Ethics, Humans, and Nature', '48S', 'This course introduces students to ethical issues arising from the way humans interact with nature. Students will study some theoretical approaches for evaluating how human society affects the planet, ecosystems, and the other animals. Theories will be drawn from philosophy, theology, and ecology, and will include Western and non-Western approaches to living in harmony with one''s environment. Key themes may include speciesism – the idea that human needs are the most important – as well as overpopulation, extinction, vegetarianism, and responsible resource management. The course will also look at how social policy shapes human choices and whether sustainability initiatives should be pursued through the public or private sector. The course will also discuss the spiritual connection between humans and the environment and how society can be organized to promote access to nature in urban communities. Restricted to first-year students admitted to the Trinity One Program. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('TRN141Y1', 'Environmental Science and Pathways to Sustainability', '48S', 'This course introduces students to fundamental issues in environmental science with a multi-disciplinary focus on human impacts on physical and biological systems, and on identifying pathways to sustainability. Key themes will include energy and resources, climate change, land use, contaminants and protecting biodiversity in the context of the Anthropocene. The course challenges students to apply the scientific method to environmental monitoring, research and problem solving through project design, data collection and analysis. The course also emphases information literacy, skills to distinguish science from pseudo-science, and considerations around representation of environmental science in the media. Restricted to first-year students admitted to the Trinity One Program. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('TRN150Y1', 'National versus International', '48S', 'The international system today faces extraordinary challenges. Understanding these challenges requires understanding the past. This seminar course briefly reviews the origins and development of the international system from the 17th century through the age of empires and the great wars of the 20th century. It then concentrates on the clash of nationalism with internationalism in the world since 1945, looking at such issues as what drives nationalism and what alternatives there are to it. We will study ideas and ideologies as well as the institutions that make up the current geopolitical world. Restricted to first-year students admitted to the Trinity One Program. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('TRN151Y1', 'Global Governance', '48S', 'Terrorism, the proliferation of arms (including weapons of mass destruction), environmental degradation, globalization, technological change, and the rise of non-state actors all pose challenges to statecraft and the management of global order. This seminar course explores the changing dynamics of global politics and the responses to them by states (and others). Topics will include an examination of new forms of international collaboration that have developed in the wake of crises in the years following the Second World War. Restricted to first-year students admitted to the Trinity One Program. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('TRN152Y1', 'Justice & Global Conflict', '48S', 'Modern states face both new and familiar challenges to protecting national security. National insecurity threatens a country''s capacity to protect the well-being of its citizens while at the same time participating in international organizations and treaties. This course explores the origins and management of international conflict from the 17th to the 21st century, focusing on the precursors to war and the markers of peace. We will also consider the ways in which our current global world order promotes and preserves justice between and within nations. Students will consider different theoretical approaches to justice between nations, and apply them to recent security issues. By studying the history of conflict and the difference between justice and injustice students will gain a deeper understanding of how current geopolitical actors can structure and affect the prospects for security policy reform moving forward. Restricted to first-year students admitted to the Trinity One Program. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('TRN160Y1', 'Public Policy and the Public Good', '48S', 'This course examines the sense of the public good that undergirds Canada''s domestic and international obligations. We examine the notion of the “public” through investigating possible answers to a central political question: what is the purpose of government? Drawing on readings in philosophy and political theory, the course considers a variety of approaches to defining the nature of the public good and how policy makers should respond when competing goods (e.g., freedom and security) clash with each other. In addition, the course looks at the treaties and conventions that articulate the responsibilities of signatory nations regarding challenges such as climate change mitigation, refugee resettlement, and foreign aid. Students will learn how international agreements either compel or encourage participation and multilateral cooperation in the absence of robust enforcement mechanisms. Restricted to first-year students admitted to the Trinity One Program. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('TRN161Y1', 'Making Public Policy Work', '48S', 'How do we know what kinds of public policy will work and what will not? How do we assess the effectiveness of a policy? An historical examination of ways in which Canadian governments have addressed a range of policy problems. Case studies of areas of federal and provincial activity today. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('TRN162Y1', 'Political Economy and Social Inequality', '48S', 'What is the relationship between capitalism and democracy? How can understanding rational choice theory inform public policy? This course will introduce students to the methods of studying the interplay between economics and politics. We will focus on specific topics to guide our quantitative analysis, which may include intergenerational poverty, the transfer of wealth, efficiency, and social stratification. We will analyse empirical results while developing critical skills for interpreting economic data and research. The course also considers global economic dynamics, transnational governance regimes, as well as the political-economic dimensions of setting global policies. By the end of the course, students will have a better understanding of global political economy, and its connection the fields of international relations and public policy. Restricted to first-year students admitted to the Trinity One Program. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('TRN170Y1', 'Ethics and the Creative Imagination', '48S', 'A seminar course that explores ethical issues through the study of works of the creative imagination that pose or provoke questions of right and wrong, good and evil, justice and injustice. The selected works will be drawn from such fields as literature, film, and the visual and performing arts. Open only to students admitted to Trinity One. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('TRN171Y1', 'Ethics and the Public Sphere', '48S', 'What does it mean to be morally required to do something? What rights do we have over ourselves, our bodies, our privacy, our choices? In this course, we will read texts from philosophy, history, political science, cultural studies and beyond that engage with the theme of ethics in the public arena. These will provide valuable analytic tools as we go on to confront contemporary issues that raise urgent ethical questions. Restricted to first-year students admitted to the Trinity One Program. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('TRN172Y1', 'Ethics and the Law', '48S', 'What is the relationship between moral values and the law? What role does the law play in enabling people to live better lives? Are legal institutions and actors subject to higher ethical standards? In this course we will read texts from legal theory and political philosophy to try to explain the connection between ethics and the law. This will provide the basis for thinking about some historical and contemporary legal cases, as well as ethical issues judges, lawyers, and lawmakers face in their professional roles. Restricted to first-year students admitted to the Trinity One Program. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('TRN191H1', 'Disaster and Terrorism: Religion and Ethics at Ground Zero', '24S', 'In response to contemporary terrorist attacks and natural disasters, many are led to cry, “The world will never be the same!” How should such statements be evaluated? What impact do they have on social and political life? This course explores religious and cultural responses to human tragedy and cultural shock. Discussion will attend to debates over the meaning of suffering, public reactions to terrorism, the traumas of natural disasters, and the role of media in covering such events. These themes are engaged from the perspectives of ethics, cultural theory, religious studies, and theology. The course focuses on popular responses to events that include: the Lisbon Earthquake of 1755, the First World War, the Holocaust, Hurricane Katrina, the Japanese experiences of Hiroshima and Fukushima, 9/11, and more recent examples of terrorism and disaster. Attention will be given to concerns such as the impact of trauma on social and political debate, the function of religious discourse in the face of tragedy, the nature of ideology, and the relationship between religion and violence. A thematic concern throughout the course will be the nature of ethical commitment in the midst of confusion and social disruption. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('TRN192H1', 'Public Health in Canada: Health for the 21st Century', '24L', 'This course deals with preventive care and population health. It will also move into new areas like healthcare and the environment (climate change) and the greening of healthcare. It will look at health as an extension of democracy – of how health extends individual rights beyond the political realm to the social realm, of how it can build social capital and knit populations together. It will look at areas inimical to health, ‘detriments to health’ and how economic inequality can lead to health inequality. Along with this it will look at ways of empowering the individual, the public as agent and a role of public engagement by major institutions. It will also push beyond the popular determinants of health to engage students in a paradigm on next steps, the future challenges in population health. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('TRN193H1', 'Canadian Health Policy: Past, Present and Future', '24L', 'This is a health systems course. It deals with illness care, individual health, and health insurance. It will take a comparative and historical approach. We will look at the genesis of Canadian healthcare, our benefits and those other countries provide (e.g., pharmacare, dental care). We will look at indirect contributors like childcare and basic income. We will examine the public-private debate. We will also take some novel approaches. One is that the university has an expanded role in the 21st century, one that involves public outreach, a role that includes healthcare. Recent academic literature on healthcare notes that it is nation-building. We will look at why. We will examine some cutting-edge ideas, like integrated care, the learning health system, the concept of customer-owners. We will explore whether our healthcare system needs to be anchored by ‘institutions of excellence’ and identify these. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('TRN194H1', 'Literature and Wicked Problems', '24L', 'This course explores contemporary literature in relation to the interdisciplinary framework of “wicked problems.” Research emphasizes that complex, entrenched problems, like government relations with Indigenous peoples or human impacts on the climate, involve interconnected systems and require approaches that cross disciplines and types of knowledge. The course examines the role of literary works (mostly 21st-century fiction) in addressing these issues of pressing concern to students as global citizens. Critical thinking, scholarly reading and database research are foundational skills that this course strengthens in order to prepare students for their writing in disciplines across the university. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('TRN195H1', 'Poetry & The Public; Social Movements & The Ethics of Response', '24L', 'Poetry & The Public considers the motivation, intent, reception, and ethics of poetic response to major political events of the late 20th and 21st centuries. Through a wide survey of poems, we will investigate not only the contextual motivation for poets responding to political issues but interrogate the formal and performative means by which they present their work to the public. Poems will be read within a wider history of social movements and civil liberties; and touch upon major historical events such as the AIDS crisis, Black liberation struggles, movements for feminist and 2SLGBTQIA+ rights, ecological and climate-change concerns, and current calls for prison abolition. We will touch upon poetic “schools” or “styles,” including the Poetics of Witness, persona poetry, the Black Arts Movement, and the Kootenay School of Writing. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('TRN196H1', 'Joy and Resistance in Diverse Storytelling', '24L', '"Can we speak about joy for once?" In contemporary literature from Black, Indigenous and People of Colour (BIPOC) authors across Canada and Turtle Island, there is a resurgence in diasporic stories that capture the joy and resistance of carving space for community against the mechanisms of the state. This course explores how BIPOC literature has intersected with social problems and activist movements, creating spaces for readers to reflect on their own lived experiences. Students will expand their creative thinking, critical reading and scholarly writing skills through multi-modal assignments that offer connections to current issues and community knowledge. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('TRN197H1', 'In the Shadow of the Vikings: Depictions of the Early Norse in Medieval, Modern, and Post-Modern Culture', '24L', 'Although rarely attested during the historical era when they were active, since the early nineteenth century the word “Viking” has been popularly applied to describe groups of Scandinavian adventurers who marauded along the frontiers of Medieval Europe: in this respect, the image of “the Viking” may be regarded as much a modern, as it is a medieval, creation. The legacy of historical “Viking activities” was a factor in the development of modern nation states in Scandinavia and the Baltic region, and their contributions to the heritage of people residing in Britain, continental Europe, the Middle East, and even the Atlantic coast of Canada have been and continue to be cited to the present day. Aspects of culture attributed to “the Vikings”—their assumed independence, courage, resourcefulness, and tenacity in the face of adversity, as well as the occult characteristics of their cosmology—have, for better and worse, inspired modern artists, writers, composers, intellectuals, explorers and even political leaders, and persist in present day literature, art, music, sport and popular culture as well. Why and how do elements of historic Viking culture continue to evoke traditions and characteristics popularly attributed to “the Vikings”? What are some implications of “Viking-ness” for those people in the post-Viking Age past and/or present who we may regard—or may regard themselves—as the “cultural descendants” of the Vikings? In this seminar, participants will study selected cultural artifacts of the “post-Viking Age,” along with recent multidisciplinary research, to observe how various “post-Viking Age” cultures and subcultures have selectively appropriated elements of the “Viking” past. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('TRN198H1', 'The Viking Phenomenon: Commerce, Conflict, and Communication along Europe''s Frontiers, 7th – 15th Century', '24L', 'Perspectives on the impact that the Scandinavian raiders and traders popularly referred to as “Vikings” had on European and World history continue to develop as the work of historians, archaeologists, linguists, and scientists expands our understanding of the past. Recent research has revised the traditional view of the “Vikings” as primarily marauding warriors; in its place, a more complex and nuanced conception of the implications that “Viking activity” had on the social, economic, and political development of the peoples with whom they came in contact has emerged. This seminar will consider the relationship between the traditional conception of the “Viking warrior” and recent research that suggests the broader impact that the “Viking Phenomenon” had upon the economic revival and sociopolitical development of medieval Europe and its frontiers. In the course of the seminar, we will examine a selection of historical records and information concerning artifacts of the material culture of “The Viking Age” in order to better understand the activities of early medieval “Vikings,” not only as warriors, but also as agents of commerce, explorers, pioneers, and rulers. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('TRN199H1', 'Classical Social and Political Thought from the 18th Century Enlightenment to the 20th Century', '24L', 'We begin with European social and political thought during the 18th century, including ideas of enlightenment and revolution. We move on to the 19th century to engage with the critical Marxist theorisation of the new “capitalist” social and political formation, and look at the reception of the Marxist view in the 20th century, all of which continues to affect the character of Western social and political thought. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('TRN200Y1', 'Modes of Reasoning', '24L/24S', 'First term: students are taught how to recognize, analyze, evaluate, and construct arguments in ordinary English prose. Second term: one or more discipline-related modes of reasoning (e.g., scientific reasoning, ethical reasoning, legal reasoning) studied with reference to a selection of contemporary social issues.', 'PHL247H1/ PHI247H1/ TRN200H1', 2, null::jsonb),
    ('TRN203H1', 'Society, its Limits and Possibilities', '24L/12T', 'Key texts from various disciplines that articulate fundamental features, limitations, and possibilities of contemporary society are introduced. Political consent, economics, governmental administration, the global / post-colonial world, historical transformation, gender politics, and media may be addressed.', 'TRN321H1 taken in 2015 Fall', 3, null::jsonb),
    ('TRN204H1', 'Introduction to Law and Legal Reasoning', '24L/12T', 'This course introduces students to legal reasoning through progressively complex exercises. First, hypotheticals expose students to basic skills required for legal reasoning. Second, they analyze simplified versions of specially selected concrete cases. Third, the course analyses real cases discussed in first year courses in law school.', null, 3, null::jsonb),
    ('TRN205H1', 'Independent Studies', null, 'Trinity Independent Studies. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('TRN225Y1', 'The Art of Health Science Discovery', '48S', 'Illustrated by contemporary examples, students go through the stages of the scientific discovery process. From initial idea, through literature review, funding (grant writing and assessment), experimental design and critical analysis of data through to the public dissemination of results by publication, the patent process and development of intellectual property. Restricted to students admitted to the Trinity One Program. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('TRN250Y1', 'Empire, Nationalism, and the History of International Relations', '24L/48T', 'Our modern world has its foundations in the development of a complex and changing system of international behaviours, customs, and rules. This course explores the global and often difficult transition from a world of empires to our contemporary world of nation-states, spanning the mid-eighteenth century to the present day. Using a global lens, this course offers an introductory historical survey using multiple perspectives and diverse settings, paying special attention to the dissolution of empire, popular revolution and mass movements, and the creation of international order. How global transformations were experienced, not only at the highest levels of power, but also by the people living amidst such change, will be an abiding concern of this course.', null, 2, null::jsonb),
    ('TRN299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('TRN299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('TRN300H1', 'Trinity Independent Studies', null, 'Trinity Independent Studies. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('TRN301Y1', 'Trinity Independent Studies', null, 'Trinity Independent Studies. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('TRN302Y1', 'Trinity Independent Studies', null, 'Trinity Independent Studies. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('TRN303H1', 'Ethics and Society', '24S', 'An exploration of the ethical dimensions of selected contemporary social issues. Restricted to students in the major program Ethics, Society, and Law.', null, 2, '{"operator": "AND", "items": ["TRN203H1"]}'::jsonb),
    ('TRN304H1', 'Law and Social Issues', '24L', 'An exploration of the legal dimensions of selected contemporary social issues. Restricted to students in the major program Ethics, Society, and Law.', 'TRN304Y1', 3, null::jsonb),
    ('TRN304Y1', 'Law and Social Issues', '48L', 'An exploration of the legal dimensions of selected contemporary social issues, focusing on law as a practice of social justice, and led by instructors with considerable practical experience. Restricted to students in the major program Ethics, Society, and Law.', 'TRN304H1', 3, null::jsonb),
    ('TRN305H1', 'Basic Principles of Law', '24L', 'An exploration of some basic legal principles in public and private law. Areas of law that may be studied include contract, tort, criminal and administrative law. Restricted to students in the major program Ethics, Society, and Law.', 'TRN305Y1', 3, null::jsonb),
    ('TRN305Y1', 'Basic Principles of Law', '48L', 'The nature and justification of legal rules as preparation for the study of basic principles of law governing the relations between individual citizens, and the relations between individual citizens and the state. A selection of contract, tort, criminal and administrative law. Restricted to students in the major program Ethics, Society, and Law.', 'TRN305H1', 3, null::jsonb),
    ('TRN307H1', 'International Experience I', null, 'A one semester research experience abroad. Students participate in a research project under the mentorship of a faculty supervisor in the host institution and gain experience of working and living abroad.', null, 3, null::jsonb),
    ('TRN308H1', 'International Experience II', null, 'Students who have engaged in a research project abroad participate in a regular forum in which they present their research projects and discuss their varied experiences of work and social engagement in different foreign environments. Students prepare a detailed scholarly article based on their research.', null, 3, '{"operator": "AND", "items": ["TRN307H1"]}'::jsonb),
    ('TRN312H1', 'Sustainability Issues in Ethics, Society, and Law', '24L/12T', 'This course focuses on core issues selected from the general domain of sustainability which are addressed through each of the three subject-area lenses of Trinity''s Ethics, Society, and Law program, namely the ethics, the socio-political context, and the legal environment of sustainability issues and initiatives.', 'TRN321H1 (Selected Topics in Ethics, Society, and Law: The Ethics, Society and Law of Environmental Sustainability), offered in Winter 2020', 3, '{"operator": "AND", "items": ["TRN203H1", "TRN204H1"]}'::jsonb),
    ('TRN320H1', 'Selected Topics in Ethics, Society, and Law', '24S', 'The course examines a selected topic in ethics, society, and law. The set of topics will be based on the research interests of an individual instructor. Both the topics and the instructor may change with each offering of the course, and the course is not expected to be offered every year.', null, 3, null::jsonb),
    ('TRN321H1', 'Selected Topics in Ethics, Society, and Law', '24S', 'The course examines a set of selected topics in ethics, society, and law. The topics will be based on the research interests of an individual instructor. Both the topics and the instructor may change with each offering of the course, and the course is not expected to be offered every year.', null, 2, null::jsonb),
    ('TRN350H1', 'Scarcity, Sustainability, and the Future of International Relations', '24L/12T', 'International Relations are changing, and changing quickly. Major challenges in global affairs, including the interrelated problems of climate change, resource scarcity, great power competition, and changes in mass politics will shape our future in uncertain and possibly dangerous ways. This course seeks to evaluate the effect of these interconnected issues on our world today, and their implications for the future. Through a series of case studies, students will be encouraged to identify future international challenges and work to develop sustainable and innovative solutions to the problems that will confront our world in the next decades and beyond.', null, 3, '{"operator": "AND", "items": ["TRN250Y1"]}'::jsonb),
    ('TRN377Y1', 'Trinity Comprehensive Paper I', null, 'Students are individually mentored by faculty experts through readings from primary literature towards preparation of a quality review article. For students in third year, students identify their faculty mentor during second year and agree to become familiar with the available textbook level material during that year in their chosen topic. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('TRN399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('TRN399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('TRN400H1', 'Trinity Independent Studies', null, 'Trinity Independent Studies. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('TRN404Y1', 'Trinity Independent Studies', null, 'Trinity Independent Studies. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('TRN405Y1', 'Trinity Independent Studies', null, 'Trinity Independent Studies. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('TRN406H1', 'Community Research Partnerships in Ethics', null, 'Students undertake research projects designed to meet the knowledge needs of ethics-oriented organizations in the broader community.', null, 2, null::jsonb),
    ('TRN407Y1', 'Community Research Partnerships in Ethics', null, 'Students undertake research projects designed to meet the knowledge needs of ethics-oriented organizations in the broader community.', null, 2, '{"operator": "AND", "items": ["TRN303H1"]}'::jsonb),
    ('TRN409H1', 'Selected Topics in International Studies', null, 'Selected Topics in International Studies', 'TRN409Y1', 3, '{"operator": "AND", "items": ["TRN250Y1", {"credits": 14.0, "department": null}]}'::jsonb),
    ('TRN409Y1', 'Selected Topics in International Studies', null, 'Selected Topics in International Studies', 'TRN409H1', 3, null::jsonb),
    ('TRN410H1', 'Researching Critical Cases in Contemporary International Relations', null, 'This course allows students with majors in International Relations to apply some of the techniques and skills they have developed during their undergraduate careers to an original research project. The course introduces several theoretical and methodological tools that are used to understand and analyze a variety of major developments affecting contemporary international relations. Students will examine the strengths and weaknesses of each research method and apply those that are most appropriate to their own IR study.', 'TRN410Y1', 3, '{"operator": "AND", "items": ["TRN250Y1", {"credits": 14.0, "department": null}]}'::jsonb),
    ('TRN411Y1', 'Selected Topics in International Studies', null, 'Selected Topics in International Studies', null, null, null::jsonb),
    ('TRN412H1', 'Seminar in Ethics, Society, and Law', '24S', 'Capstone Seminar in Ethics, Society, and Law. Students must be in their final year of registration in the Major Program: Ethics, Society and Law. For detailed description of topics, please visit https://www.trinity.utoronto.ca/study-arts-science/ethics-society-law/courses-program-requirements/. Students are not eligible to enrol in this course more than once, for credit.', null, 2, '{"operator": "AND", "items": ["TRN303H1"]}'::jsonb),
    ('TRN419Y1', 'Comparative American, British and Canadian Foreign Policy', '48S', 'The origins and evolution of American, British and Canadian foreign policy from the late 18th century to the present. Policies are compared in order to understand the development of these countries as nations and actors in the international community.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('TRN421Y1', 'Fragile and Conflict-Affected States in Global Politics', '48S', 'Since the end of the Cold War, fragile and conflict-affected states have been widely viewed in the international relations field as one of the preeminent challenges to international security and global governance. Western countries have typically responded to this challenge by launching interventions aimed at building new states that can be integrated into the global, liberal order. This course will dissect the liberal peacebuilding and statebuilding project and explore its broader impact and implications for the international system.', null, 3, null::jsonb),
    ('TRN425Y1', 'Law Workshops Course', null, 'Students attend workshops in the Faculty of Law, meet for related discussion and complete related assignments. Enrolment is restricted to qualified fourth-year students registered in the Major Program Ethics, Society, and Law.', null, 3, '{"operator": "AND", "items": ["TRN303H1"]}'::jsonb),
    ('TRN477H1', 'Trinity Comprehensive Paper II', null, 'The preparation of a publication quality review article typically involves extensive editing. Students are individually mentored by faculty experts to take the review paper generated in  TRN377Y1 and edit the structure, content and style to produce a publication quality review article. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": ["TRN377Y1"]}'::jsonb),
    ('TRN478H1', 'Science Writing for Non-Scientific Audiences', null, 'The course aims to train senior-level science students in a wide range of writing genres, focusing on a diversity of non-scientific audiences and writing styles. In addition, students learn to read and analyze texts in order to understand rhetorical strategies and devices.', 'Non-science students, first or second year students.', 4, null::jsonb),
    ('UNI101H1', 'Citizenship in the Canadian City', '36S', 'Who belongs? Who governs? Who decides? In this course, you will examine the concepts of citizenship, public space, political membership, civic responsibility, and belonging. You will address topics such as Indigenous sovereignty claims, urban multiculturalism, public housing, and greening the city. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('UNI102H1', 'Performing the City I', '36S', 'In this course we learn about different practices of performative engagement with the city and experiment with them through exercises and creative activities. The goal is to gain, through this mode of embodied engagement with the city, a critical understanding of urban space as a diverse social, cultural, and physical environment. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('UNI103H1', 'Gradients of Health in an Urban Mosaic', '36S', 'In this course, you will examine how Toronto''s varied communities access and use health care, and how they may encounter barriers in doing so. You will study how economic disparities, shifting demographics, and government policies affect health policy and the right to access resources. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('UNI104H1', 'Sex in the City', '36S', 'You will learn about the sexual politics of the city and how cities and their neighbourhoods become sexualized and desexualized spaces. In Sex in the City, you will examine what “sex” means to Toronto''s varied, multicultural communities by looking at urban space, cultural productions, law enforcement, safety and health resources and more. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('UNI106H1', 'Performing the City II', '36S', 'Further exploration of connections between the performing arts, urban spaces, and cultural diversity; complementing  UNI102H1. How does theatrical performance affect how people perceive the city? What are the alternatives to established theatres, and how does community activism inform performing arts in Toronto? Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('UNI197H1', 'Hamilton: Musical and History', '24S', 'This course examines the American revolution and its reception in the musical “Hamilton.” The American revolution generated multiple stories that included and excluded actors, peoples, perspectives, and more. This course delves into the American revolution and the diversity of those engaged in it and affected by it. The songs, performances, and reception of the musical “Hamilton” are a key resource for exploring the events and role of the American Revolution. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('UNI198H1', 'Why Go to University? The Changing Role and Purpose of Higher Education', '24S', 'Is higher education about job preparation or about giving students an opportunity to learn about themselves and the world around them? Can higher education in Canada achieve both these aims? This course engages with the spirited conversations and scholarly debates about the ideals of a liberal arts education and how these connect with ancient and contemporary arguments about citizenship. We explore the impact on higher education of globalization and what some call the “corporatization” of universities. Students will be encouraged to think, read, research and write about various models of higher education and explore questions suggested by these debates. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('UNI199H1', 'The Construction of Race in America: A History', '24S', 'The course will explore the origins of racial categories in America. Drawing on primary sources such as memoirs, film, and government records as well as writings by scholars, we will examine how beliefs about these categories changed over time and with what consequences for the unfolding of American history. Arriving at the present day, we will consider such contradictory developments as the accelerating influence of Black Lives Matter and the headline-grabbing white nationalism on display at the “Unite the Right” rally in Charlottesville, Virginia, August, 2017. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('UNI299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('UNI299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('UNI393Y1', 'University College Independent Studies', null, 'An opportunity to design an independent research course of study at the 300 level not otherwise available within the Faculty of Arts and Science. Students must be registered at UC or in a UC-affiliated program. Not eligible for CR/NCR option. Students must submit an application form that includes a written proposal and confirms that a faculty member has agreed to supervise. Applications must be submitted to the UC Programs Office (UC 173) for approval by the Vice-Principal. Applications are due before the first day of course enrolment. Application form is available at the University College website at https://www.uc.utoronto.ca/programs-study-academic-programs-independent….', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('UNI394H1', 'University College Independent Studies', null, 'An opportunity to design an independent research course of study at the 300 level not otherwise available within the Faculty of Arts and Science. Students must be registered at UC or in a UC-affiliated program. Not eligible for CR/NCR option. Students must submit an application form that includes a written proposal and confirms that a faculty member has agreed to supervise. Applications must be submitted to the UC Programs Office (UC 173) for approval by the Vice-Principal. Applications are due before the first day of course enrolment. Application form is available at the University College website at https://www.uc.utoronto.ca/programs-study-academic-programs-independent….', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('UNI399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('UNI399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('UNI495Y1', 'University College Independent Studies', null, 'An opportunity to design an independent research course of study at the 400 level not otherwise available within the Faculty of Arts and Science. Students must be registered at UC or in a UC-affiliated program. Not eligible for CR/NCR option. Students must submit an application form that includes a written proposal and confirms that a faculty member has agreed to supervise. Applications must be submitted to the UC Programs Office (UC 173) for approval by the Vice-Principal. Applications are due before the first day of course enrolment. Application form is available at the University College website at https://www.uc.utoronto.ca/programs-study-academic-programs-independent….', null, null, '{"operator": "AND", "items": [{"credits": 15.0, "department": null}]}'::jsonb),
    ('UNI496H1', 'University College Independent Studies', null, 'An opportunity to design an independent research course of study at the 400 level not otherwise available within the Faculty of Arts and Science. Students must be registered at UC or in a UC-affiliated program. Not eligible for CR/NCR option. Students must submit an application form that includes a written proposal and confirms that a faculty member has agreed to supervise. Applications must be submitted to the UC Programs Office (UC 173) for approval by the Vice-Principal. Applications are due before the first day of course enrolment. Application form is available at the University College website at https://www.uc.utoronto.ca/programs-study-academic-programs-independent….', null, null, '{"operator": "AND", "items": [{"credits": 15.0, "department": null}]}'::jsonb),
    ('URB234H1', 'Cities in Popular Culture', '24L', 'By exploring different popular culture phenomena such as the emergence of hip-hop in the Bronx, Batman''s Gotham, and Nollywood, this course works to examine the contributions of popular culture in shaping our understandings of cities (as well as providing different perspectives of the city and the urban experience than is generally captured in scholarly/academic literature). Popular culture becomes a vehicle by which we will explore different aspects of urban life and urban representation.', 'INI234H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('URB235H1', 'A Multidisciplinary Introduction to Urban Studies I: Theoretical Foundations of City Building', '24L', 'Focuses on the theoretical foundations of urbanization, urban change, and city building, with particular attention on global urban growth, history of contemporary urbanization, urban planning, governance, built form, and economic development. These topics are explored through a multidisciplinary lens, with an emphasis on understanding urban transitions over time and their meaning for contemporary urban experience.', 'INI235H1,  INI235Y1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, {"operator": "OR", "items": ["ECO101H1", "ECO102H1", "ECO105Y1", "GGR107H1", "GGR112H1", "GGR124H1", "POL101H1", "POL106H1", "POL107H1", "POL109H1", "SOC100H1", "SOC150H1", "JAV120H1", "JAV151H1", "JAV152H1", "ARC181H1"]}]}'::jsonb),
    ('URB236H1', 'A Multidisciplinary Introduction to Urban Studies II: Urban Challenges and Theoretical Application', '24L', 'Cities are centres of innovation and creative energy, but they also face significant and pressing challenges. This course explores various urban issues including inequality, eroding infrastructure, and concerns arising from globalization, while also examining the ways in which municipal governments and urban citizens are imagining and implementing potential solutions to these challenges.', 'INI235Y1,  INI236H1', 3, '{"operator": "AND", "items": ["URB235H1"]}'::jsonb),
    ('URB333H1', 'Social Justice in the City', '24L', 'How do power and dominance consolidate in urban settings? How do individuals and communities contest this consolidation, and claim spaces and rights in the city? These questions will be taken up through a range of critical approaches, including Indigenous, critical race feminist, political economy, queer, and anarchist perspectives. Students will have the opportunity to carry out interview-based research on an issue of equality and social justice that matters to them.', 'INI333H1', 3, null::jsonb),
    ('URB334H1', 'Urban Field Course', '12S', 'Students will have the opportunity to travel to a destination city for a week-long examination of specific social, economic, physical, and/or environmental issues. The trip will include meetings with municipal representatives and other decision-makers (public and possibly private). The findings of the trip supplemented by bibliographic research and in-class discussion will form the basis of a major research essay. Each student is required to pay the cost of transportation and accommodation. Not eligible for CR/NCR option.', 'INI334H1', 3, '{"operator": "AND", "items": ["URB235H1", "URB236H1"]}'::jsonb),
    ('URB335H1', 'City Challenges, City Opportunities in a 21st Century Toronto', '12L/12S', 'Over the last 50+ years, Toronto has become a national and international centre of economic activity, with a vibrant arts and culture scene and world-renowned research, educational, and health institutions. Additionally, the City has become one of the most culturally diverse cities in the world. That said, Toronto also struggles with deep inequalities along many different axes, an affordable housing crisis, underfunded infrastructure needs, and many other challenges. This course provides a window into how the leadership at the City of Toronto think and approach these and other issues as the City works to plan for the recovery from COVID-19.', 'URB338H1 (Advanced Topics in Urban Studies I: City Challenges, City Opportunities in a 21st Century Toronto), offered in Fall 2021', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('URB336H1', 'Creative Cities', '24L', 'A prominent thesis in the fields of planning and economic geography is that the presence of creative occupations in a city correlates positively with the overall health of urban regions. This course will investigate the nature of this link from theoretical and empirical perspectives and examine its potential usefulness in a planning/policy context.', 'INI336H1,  INI336Y1', 3, null::jsonb),
    ('URB337H1', 'Housing and Homelessness', '24L', 'Toronto, like other global cities, is characterized by a stark dichotomy: upscale residential and commercial development transforms the landscape, even while increasing numbers of residents are forced to live on the streets, in encampments, in shelters, or crowded into unaffordable and substandard housing. This course will examine that paradox and activism that is trying to achieve the federal government''s stated goal: “By 2030, everyone in Canada has a home that they can afford and that meets their needs”. Through readings, discussions, guest presenters, and activities, we will trace the links between housing, homelessness, and urban politics; review policies and trends at the municipal, provincial/territorial and national levels; and connect with urban movements to contest displacement.', 'INI337H1', 3, null::jsonb),
    ('URB338H1', 'Advanced Topics in Urban Studies I', '24L', 'This course will expose students to a range of contemporary theoretical, analytical, and policy oriented debates in Urban Studies. The emphasis will be on establishing a broad knowledge base in the multifaceted field of urban studies. The exact topics to be covered will fall broadly under the banner of urban socioeconomic change, and specific syllabi, year to year, will follow contemporary and emerging debates.', null, 3, null::jsonb),
    ('URB339H1', 'Divided City / United City', '24L', 'Focus on the impact of increased economic inequality and economic polarization trends that are reshaping Canada''s metropolitan areas, changing neighbourhoods, and affecting the lives of our diverse urban population. Using the Toronto area as an example, students explore the consequences of these trends and the implications for public policy.', 'INI339H1', 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('URB342H1', 'Qualitative Research in Urban Studies', '24S', 'This course provides students an opportunity to craft and initiate an Urban Studies capstone research project. Students will gain knowledge, experience and insight in utilizing qualitative research methods including interviewing, focus groups, observational analysis and other techniques. Seminars and assignments focus on the application of qualitative methods to each student''s selected urban research question.', 'INI342H1', 3, null::jsonb),
    ('URB430H1', 'Advanced Topics in Urban Studies II', '24L', 'This course is meant to be a senior complement to  URB338H1 whereby important theoretical, analytical and/or policy debates are addressed in a research seminar format. Students in  URB430H1 will be expected to extend, or refine research topics identified and explored in  URB338H1 in a major independent research project. Students will present their proposals, their progress reports, and their final results to the instructor and the class.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "URB235H1", "URB236H1"]}'::jsonb),
    ('URB431Y1', 'Special Topics in Urban Studies', null, 'Special topics courses are offered periodically for senior students in the Urban Studies Program. Offerings in any given year will depend on program priorities, availability of specialized expertise and funding. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('URB432H1', 'Special Topics in Urban Studies', null, 'Special topics courses are offered periodically for senior students in the Urban Studies Program. Offerings in any given year will depend on program priorities, availability of specialized expertise and funding. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('URB433H1', 'Special Topics in Urban Studies', '24S', 'Special topics courses are offered periodically for senior students in the Urban Studies Program. Offerings in any given year will depend on program priorities, availability of specialized expertise and funding. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('URB434Y1', 'Independent Research in Urban Studies', null, 'Designed to allow strong students in the Major and Specialist programs to extend a piece of urban research under the supervision of a faculty member from any aligned department. Choice of ''H'' or ''Y'' session pursuant to the scope of the research envisioned, the proposed supervisor''s assessment of depth of the inquiry, and the approval of the program director. Proposals, including a letter from an agreeable supervisor should be submitted to the program director by June 1 for a Fall or Year session course and by November 1 for a Spring session course. Not eligible for CR/NCR option.', 'INI434Y1', null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "URB235H1", "URB236H1"]}'::jsonb),
    ('URB435H1', 'Independent Research in Urban Studies', null, 'Designed to allow strong students in the Major and Specialist programs to extend a piece of urban research under the supervision of a faculty member from any aligned department. Choice of ''H'' or ''Y'' session pursuant to the scope of the research envisioned, the proposed supervisor''s assessment of depth of the inquiry, and the approval of the program director. Proposals, including a letter from an agreeable supervisor should be submitted to the program director by June 1 for a Fall or Year session course and by November 1 for a Spring session course. Not eligible for CR/NCR option.', 'INI435H1', null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "URB235H1", "URB236H1"]}'::jsonb),
    ('URB436H1', 'Independent Research in Urban Studies', null, 'Designed to allow strong students in the Major and Specialist programs to extend a piece of urban research under the supervision of a faculty member from any aligned department. Choice of ''H'' or ''Y'' session pursuant to the scope of the research envisioned, the proposed supervisor''s assessment of depth of the inquiry, and the approval of the program director. Proposals, including a letter from an agreeable supervisor should be submitted to the program director by June 1 for a Fall or Year session course and by November 1 for a Spring session course. Not eligible for CR/NCR option.', 'INI436H1', null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "URB235H1", "URB236H1"]}'::jsonb),
    ('URB437Y1', 'Urban Experiential Learning in Toronto & the GTA', '72S', 'A method of studying city issues that combines readings, seminar discussions, and field trips with an 8 hour / week internship in the office of a municipal politician, local government, or non-profit organization. Readings focus on community development, urban planning, economic development and local governance. Students must fill out a ballot for the course (available by contacting the Urban Studies Program Office) by June 1st. Enrolment in this course is competitive and at the discretion of the Urban Studies Director and/or course instructor.', 'INI437Y1,  INI306Y1', 3, '{"operator": "AND", "items": ["URB235H1", "URB236H1"]}'::jsonb),
    ('URB438H1', 'Advanced Urban Research Project', '24S', 'This course will allow students to investigate an urban topic of their choice in a guided seminar environment. This course will guide students through the various steps of the research process including: proposal writing and refinement, secondary research, primary data acquisition, analysis and the production of a senior research paper. The course emphasizes the connections between the design, implementation and write-up of an in-depth research paper. Not eligible for CR/NCR option.', 'INI438H1,  INI438Y1', 3, '{"operator": "AND", "items": ["URB235H1", "URB236H1"]}'::jsonb),
    ('URB439H1', 'Cities and Mega-events: Place-making, Contestation and Urban Citizenship', '24S', 'Mega-events, like the Olympics, give cities the opportunity to showcase themselves to the world, but the production of television-friendly urban images do much to obscure the processes, compromises and social consequences in host cities. These events are powerful tools for city branding. They are also potential opportunities for social movements and other groups and individuals to highlight their own sets of concerns. This course will explore the challenges and opportunities that cities face in hosting such events.', 'INI439H1;  INI430H1 (Advanced Topics in Urban Studies II: Cities and Mega-Events: Conflicts and Opportunity) offered in Winter 2014;  INI332H1;  INI432H1 (Special Topics in Urban Studies: Cities and Mega-Events), offered in Fall 2016', 3, '{"operator": "AND", "items": [{"credits": 12.0, "department": null}]}'::jsonb),
    ('URB440H1', 'The Changing Culture of Regent Park', '24L', 'This course is a collaboration with the organization Regent Park Focus Youth Media Arts Centre, a not-for-profit organization that was established to counter negative stereotypes about the Regent Park community. Together, University of Toronto students and Regent Park Focus youth members will learn about media projects initiated by young people across the world, and how these creative forms of communication, organizing, and expression spurred change and social movements in their respective communities. U of T students and Regent Park Focus youth will work together to create their own media project about the neighborhood.', 'URB430H1 (The Changing Culture of Regent Park, offered in Fall 2022, Winter 2024),  INI430H1 (Youth, Arts and Engagement in Cities, offered in Winter 2019, Winter 2020)', 3, '{"operator": "AND", "items": ["URB235H1", "URB236H1", "URB342H1"]}'::jsonb),
    ('URB442H1', 'Urban Studio: Public Participation in Policy Making', '24S', 'This course will provide a broad overview of the roles of both the citizen and the professional practitioner in advancing effective and meaningful public participation in the policy-making process, particularly as it relates to city planning. Through an examination of a mix of theoretical frameworks and case studies from Toronto and elsewhere, you will gain an understanding of the ways in which effective public participation can contribute to the maintenance of a healthy democratic society while also exploring some of the key challenges and opportunities faced by public participation practitioners today. The course has two key objectives: to give you a practical understanding of all of the elements of an effective public participation process, and to explore how public participation processes can be designed to be more inclusive and effective. In addition, students will be able to apply this knowledge towards the development of a project or report for a client.', 'Urban Studio: Public Participation in Policy Making taken under  URB432H1 (offered in Fall 2022)/  INI432H1 (offered in Summer 2017, 2018, 2019, 2020, 2021)', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('UTP100H1', 'Themes in World History', '24L', 'Surveys the development of human societies from their origins to the present. Topics may include the environment, cultural development and interaction, the creation and nature of belief systems, political, economic and social structures, gender relations, and the relationship between global patterns and local development. Restricted to students enrolled in the UTPrep program.', 'IFP100H1/ IFP100Y1', 3, null::jsonb),
    ('VIC101H1', 'Conflict Theory and Practice', '24S', 'This course is a general orientation to conflict theory, and develops a basic understanding of essential conflict resolution principles that will complement the study of conflict theory. The course will examine the differences between conflicts and disputes, the functions and desirability of conflict, and the conditions that facilitate conversion of conflicts from destructive to constructive. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC102H1', 'Ethics and Choices in Times of Crisis', '24S', 'This course examines a specific event, or events, in relation to the public sphere. The course will use events or an event as an entry point to discuss the nature of society including topics such as major revolutions, economic crises, the impact of the appearance of significant artistic or cultural works, and the impact of technological changes. Not eligible for CR/NCR option.', 'VIC102Y1', 2, null::jsonb),
    ('VIC103H1', 'Leadership, Narrative, and Creativity', '24S', 'This course examines what it means to be a leader through narrative presented in media such as text or film. Such works of creative fiction aspire not simply to depict actions and events, but also to lay bare the inner psychology of protagonists. They capture and convey realities with a psychological depth that social scientists cannot always replicate. Students will study such narratives to understand various kinds of leadership skills and leadership types. By creating narratives of their own, students will practice the communication skills that leaders need. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC105H1', 'Odysseys: The Search for Meaning', '24S', 'Metaphors and motivations of journeying have long intrigued human beings as they have attempted to understand the meaning of their existence: the setting out, the seeking for a desired object, the pilgrimage of religious observance, and the longing to return home. Through texts, art, music and film, this course will explore some of the shaping journey-myths of our culture from classical, Hebrew, medieval and modern sources. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('VIC106H1', 'Psychology and Society', '24S', 'This course explores central developments and ongoing controversies in the scientific study of the human mind, brain and behaviour. It examines topics such as: psychoanalysis, behaviourism, humanistic psychology, evolutionary psychology, intelligence testing, and feminist perspectives. Goals include understanding the historical evolution and social relevance of scientific psychology. Not eligible for CR/NCR option.', 'VIC206H1', 2, null::jsonb),
    ('VIC107H1', 'Evolution, Genetics, and Behaviour', '24S', 'In this course we examine major episodes in the history of evolution and genetics in the twentieth century. Topics include Darwinian evolution, sociobiology and evolutionary psychology, eugenics, and genetic screening and therapy. We will examine different views about the control of evolution and genetic manipulation in their socio-cultural-economic context and discuss the ethical and social implications of those views. Not eligible for CR/NCR option.', 'VIC207H1', 2, null::jsonb),
    ('VIC108H1', 'Belonging, Imagination, and Indigenous Identity', '24S', 'This course will examine a number of questions related to Indigenous identities as they have been constituted through collective belonging and cultural representation. Topics covered may include: language, the arts, cinema, ecology, religion, ritual, and the enduring legacy of colonialism. Not eligible for CR/NCR option.', 'VIC108Y1', 3, null::jsonb),
    ('VIC109H1', 'Innovators and Their Ideas', '24S', 'A study of the ideas and concerns of innovators who questioned traditional views and values. The course includes creative thinkers who challenged basic concepts on politics, literature, religion, and society. Not eligible for CR/NCR option.', 'VIC109Y1', 2, null::jsonb),
    ('VIC110H1', 'Critical Perspectives on Society', '24S', 'By means of short texts, film or art works this course explores such themes as the effect of technology on the political, the nature of democracy, the question of resistance through art and the role of violence in the social. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC112H1', 'Puzzles, Discovery and the Human Imagination', '24S', 'There has never been a period of time, nor has there ever been a culture, without some kind of puzzle tradition. Are puzzles just playful artefacts, intended merely to entertain? Or are they mirrors of something much more fundamental in human life? The course will take a close look at what puzzles tell us about the human mind and human culture. Not eligible for CR/NCR option.', 'VIC112Y1', 2, null::jsonb),
    ('VIC113H1', 'Encountering Distant Climes: The Literature of Travel and Exploration', '24S', 'This course will study accounts of world travelers and explorers from the Middle Ages to the present, including representative examples drawn from the Age of Exploration, the Grand Tour, scientific and map-making expeditions, and the contemporary genre of travel writing. Particular attention will be given to the trans-cultural nature of travel, and the interactive aspects of the gulf between the observer and those observed. Students will analyze the diverse motivational factors behind excursions and expeditions, and apply a critique to written accounts in light of such factors as self-discovery, knowledge and imagination, Eurocentrism, orientalism, cultural relativism, colonialism/imperialism, race, gender, and eco-tourism. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('VIC114H1', 'Renaissance in Popular Culture', '24S', 'This course explores the depiction of the Renaissance in a wide range of plays, films and novels. The focus is on the exchange between film, fiction, and ''fact'', and on how the values and concerns of the present shape creative recreations of the past in popular culture. Not eligible for CR/NCR option.', 'VIC114Y1', 1, null::jsonb),
    ('VIC115H1', 'Imagined Power: Literature and Film', '24S', 'In this course we will study a number of literary and cinematic works that take up questions of power, duty, rights, responsibility, and freedom. Our texts will be drawn from a long history, and from many parts of the world. The sequence however will not be chronological. Not eligible for CR/NCR option.', 'VIC115Y1', 1, null::jsonb),
    ('VIC116H1', 'Politics of the Pen', '24S', 'A study of how literature challenges prevailing political beliefs and social norms. We will situate our discussion in the broader context of human rights and freedoms. We will examine cases where literature has been censored and writers have been imprisoned or driven into exile. Part of this course involves a community service-learning component. We will consider how this literature contributes to debate and advocacy around issues of social justice. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC117H1', 'Understanding the Performing Arts: Interpretation and Expression', '24S', 'This course examines two key issues about the performing arts that concern both artists and theorists: the nature of interpretation and of expression. What might we mean when we say that a work, a piece of music or a dance for example expresses something? What is it to express? And what is the nature of interpretation? Are there any constraints or boundaries on interpretation? We will draw on both philosophers and non-philosophers to explore these sorts of questions. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('VIC119H1', 'Myths and Legends in Modern Contexts', '24S', 'This course provides an introduction to modern forms of ancient narratives, exploring the ways in which selected ancient literary sources and myths have been adapted to modern Canadian literature. Ancient narratives or ''old stories'' are often reused, reinterpreted or reconstructed in modern narratives and given new relevance in a contemporary context. Students will encounter sources and contexts of ancient narratives. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('VIC121H1', 'Evaluating Healthcare: Problems and Solutions', '24S', 'This course introduces students to the study of healthcare by asking foundational questions about how evidence and knowledge are produced in the context of healthcare problems. Students will explore how different frameworks for clinical practise (e.g. Evidence-based Medicine, Person-Centered Healthcare) conceptualize evidence and how different methodologies impact how healthcare research is conceived, reported, and understood. Students will learn to critically appraise healthcare research studies and assess their evidence value and implications for clinical practice. Restricted to first-year students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('VIC122H1', 'Scientific Evidence in Public Policy', '24S', 'This course investigates issues arising from the translation of scientific evidence for public consumption, including in the development of public policy and in confronting problems of social and global significance. Areas of focus will include climate change, global health, and clinical medicine. Students will explore concepts including the perception and communication of risk, the generalizability of research findings, probabilistic and mechanistic thinking, and the use and abuse of scientific authority and “expertise” in public discourse. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC134H1', 'Globalization', '24S', 'This interdisciplinary course explores the contemporary character of globalization. The world is shrinking as money, goods, people, ideas, weapons, and information flow across national boundaries. Some commentators assert that a more tightly interconnected world can exacerbate financial disruptions, worsen the gap between rich and poor nations, undermine democracy, imperil national cultures, harm the environment, and give unconstrained freedom to predatory corporations. Others proclaim that globalization - understood as capitalism and free markets - fosters economic growth, encourages creative collaboration, inspires technological breakthroughs, and enhances human prospects for a better life, in rich and poor countries alike, in unprecedented ways. Our task is to evaluate the evidence and draw our own conclusions. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC135H1', 'The Death of Meaning', '24S', 'In The Origin of Species, Darwin concluded there was no evidence to suggest that life was designed by a higher power. A corollary of this is that our lives lack any necessary purpose or meaning. Our readings will be directed to the question of what it means to lack ''Meaning''. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC136H1', 'How to Study Everyday Life', '24S', 'An introduction to the academic study of everyday life. A cross-disciplinary discussion class drawing on a wide variety of examples from ordinary life, fantasy, and culture. We situate the apparently innocuous within larger patterns of social relations and social change. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC137H1', 'Science and Science Fiction', '24S', 'Based on reading and discussion of science fiction and popular science in the context of social issues, this seminar course explores the fantastic visions of humanity''s future inspired by scientific advances during the twentieth century. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC141H1', 'Discovery and Revolution', '24S', 'This course examines the emergence of a global modern world in relation to the upheavals of the Renaissance (1350-1700) and its discoveries and innovations in culture and society. Not eligible for CR/NCR option.', 'VIC141Y1', 2, null::jsonb),
    ('VIC142H1', 'Machiavelli: The Politics of Power', '24S', 'The name of Machiavelli unleashes powerful opinions and responses and conjures up trickery, duplicity and cynicism. Yet Machiavelli himself is arguably the least Machiavellian of political figures of the Italian Renaissance. This course examines the writings of Niccolò Machiavelli, placing them in their historical context in order to understand this most controversial figure of the Renaissance, his influence and his lasting legacy. Not eligible for CR/NCR option.', 'ITA198H1 (Machiavelli and Machiavellianism);  VIC141Y1', 2, null::jsonb),
    ('VIC145H1', 'Mental Health Literacy in Education', '24L', 'This course introduces students to fundamental concepts and issues related to wellbeing and mental health through the lens of mental health literacy. Mental health literacy refers to the knowledge and understanding of mental health conditions, including the ability to recognize symptoms, seek help and know how to support others. Students will investigate varied and global approaches towards achieving wellbeing and situate mental health within individual and social contexts with an emphasis on lived experience. Indigenous, Eastern and spiritual conceptions of wellbeing will be introduced. Mental health literacy in schools and other contexts of learning, will be discussed. The course will equip students with knowledge of how to support their own wellbeing, community wellbeing, and the wellbeing of those they serve now and will serve in the future. Restricted to first-year students. Not eligible for CR/NCR option.', 'VIC150H1,  VIC151H1,  VIC152H1,  VIC153H1', 3, null::jsonb),
    ('VIC150H1', 'Theory and Practice of Teaching: Theoretical Perspectives', '24S', 'This course introduces past and contemporary theories and perspectives on teaching and learning in schools and broader society. While there is consensus on the fundamental role that both learning and teaching play in society, a range of perspectives exists on what comprises “teaching” and “learning”, how they occur, and how they might be facilitated through designed environments. The course begins with an exploration of major theories of learning and their implications for practice. It then examines several pedagogical frameworks and perspectives of teaching and their implications for educational practice. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC151H1', 'Theory and Practice of Teaching: Professional Practice', '24S', 'This course introduces the theories and practices of teaching through analysis of three main themes: planning and implementing inclusive instruction, establishing a classroom context to support diverse learners, and analyzing professional concerns for teachers. Students will be involved in a volunteer placement in a school or community-based setting. Field experience is central to the course with students expected to apply course ideas in their volunteer work and reflect on their experiences in seminars. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC152H1', 'School and Society: Historical and Contemporary Contexts', '24S', 'This course investigates the historical and contemporary roles of the school and formal education system and explore changes in these organizations over time. The course examines schools and learning as social, political, intellectual, and economic phenomena. Topics covered include the history of Canada'' education system, the purposes of formal schooling, the role of the school, education and the law, education policy and school curriculum. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC153H1', 'School and Society: Equity and Social Justice in Education', '24S', 'This course will examine education as a human right and through a human-rights- based lens, explore themes of equity and diversity, global education, Indigenous knowledge and perspectives, and decolonizing education. Contexts of discussion will include early-years learning, elementary and secondary school, post-secondary education, and other community-based learning settings, both locally and globally. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC159H1', 'Vic One Hundred Special Topics Seminar', '24S', 'Topics vary from year to year. Not eligible for CR/NCR option. Breadth requirement will vary from year to year depending on the course topic. Please refer to course website for more information: https://vic.utoronto.ca/academic-programs/special-topics-courses/vic159h', null, null, null::jsonb),
    ('VIC159Y1', 'Vic One Hundred Special Topics Seminar', '48S', 'Topics vary from year to year. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC162H1', 'Cultural Forms and Their Meanings', '24S', 'A study of culture with a view to developing basic concepts with examples drawn from the visual arts, music, film, literature, architecture, and/or local urban artefacts. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('VIC163H1', 'Cultural Forms and Their Meanings: People and Ideas', '24S', 'A study of culture with a view to developing basic concepts with examples drawn from the visual arts, music, film, architecture, and/or local urban artefacts. We will emphasize how contemporary thought has affected the practice of everyday life. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC164H1', 'Ideas and Their Consequences: Literary and Artistic Realms of the Imagination', '24S', 'A study of the ideas and concerns of creative thinkers and their impact upon cultures. The course includes literary, scientific and/or religious intellectuals from the major traditions. Attention to modes of reasoning, cultural definition and expression. Emphasis on philosophical and artistic concepts. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC165H1', 'Ideas and Their Consequences: Isolation and Communion in Modern Culture', '24S', 'A study of art, with a focus on poetry, as an essential mode of experience and knowledge, in the context of contemporary and modern society. Along with literary artists, the course includes writers on history and sociology and presents the interplay between artistic vision and socio-political situations. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC166H1', 'Common Vices and Neglected Virtues: Intro to Ethics of Character', '24S', 'Vice is popular: a prestigious university press has brought out a series of seven books on the Seven Deadly Sins. This course examines such questions as the following. Are greed, lust and gluttony just bad names for necessary and otherwise acceptable instincts? What is the place, in a good human life, of such qualities as honesty, trust, civility and the like? Are vices and virtues culturally determined or a matter of individual preference? Can character be taught, or is it rather a matter of genes and luck? Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC167H1', 'Ideas and Fine Thoughts', '24S', 'This course examines how political ideas are formed and developed through literature, art, plays, essays and philosophical works in the twentieth century. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('VIC168H1', 'Identity and Equality in the Public Sphere', '24S', 'This course explores current legal and philosophical debates around equality, discrimination, and the shaping of individual and group identities. It addresses the way values, affiliation, and identities have an impact on the public sphere of law and policy-making – and the ways in which law and policy, in turn, shape our conceptions (and misconceptions) of people''s identities. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC169H1', 'Ethical Living in a Pluralistic World', '24S', 'This course examines different values, beliefs, and traditions relating to the natural and social world, ethical living, and the common good. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC170Y1', 'The Impact of Science on Our Society', '48S', 'How rhetoric and statistical analysis are used to communicate scientific observations and theories to different audiences will be examined in lectures and seminars. Uncertainty, belief, evidence, risk assessment, random error and bias will be discussed using examples drawn from literature, the arts and the physical, life and social sciences. Students will prepare a research grant application on a scientific topic of their own choice. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC171Y1', 'Methodology, Theory and Practice in the Natural Sciences', '48S', 'An examination of scientific theories and their logic in life and physical sciences. Experimental design, novel device production, data analysis and modeling will be discussed using examples drawn from primary source material in the natural sciences. Students will prepare a research paper on a topic designed in consultation with the instructor. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('VIC172Y1', 'Physical Sciences Today', '48S', 'How is science performed and what enables scientific progress? What are our responsibilities as scientists? We base the discussion mostly on the development of microscopy tools. We look at how scientific discoveries affect and were affected by society. This course explores the complementary skills and knowledge needed by modern scientists. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC173Y1', 'Philosophy of Science for Physical Scientists', '48S', 'This course introduces students to some of the issues in the philosophy of science, in general, and in the philosophy of physics, in particular. Topics include the scientific method and its controversies, the meaning of time and its properties, realism versus competing approaches, thought experiments, and quantum mechanics. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC181H1', 'Events in the Public Sphere: World Affairs', '24S', 'This course will review issues in contemporary world affairs, from the fall of the Berlin Wall to the present day. The course will examine the politics and practice of foreign policy decision making. Issues to be covered include the collapse of the Soviet Union, intervention in humanitarian crises, and the conflicts in Afghanistan and Iraq. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC183H1', 'Issues in the Public Sphere: Understanding Public Policy', '24S', 'This course explores how public service and citizenship are developed. Topics may include the role of law and government, civil liberties, rights and responsibilities, and the creation of policy, as well as how these factors shape collective memory. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('VIC184H1', 'Individuals and the Public Sphere: History, Historiography and Making Cultural Memory', '24S', 'A seminar course that examines the contribution of an individual or individuals to the public sphere. The course will explore how public service and citizenship are developed in social, philosophical, and cultural contexts. We will examine our evolving role in developing collective, cultural and counter memory. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC185H1', 'Democracy and Dictatorship', '24S', 'This course uses events to discuss the nature of society including major revolutions, economic crises, and the impact of significant artistic, cultural and technological developments. Emphasis on our responsibilities towards social justice. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC186H1', 'The Art and Literature of Leadership 1', '24S', 'What is a leader? Are leaders born or are they made, and if they are made is there a craft to being able to lead others? Through works of art, film, and literature, this course examines the various types of men and women who become leaders from natural-born talents to statesmen and state-crafters and individual entrepreneurs with the purpose of defining those qualities that make for the leaders of tomorrow. Restricted to first-year students. Not eligible for CR/NCR option.', 'VIC186Y1', 1, null::jsonb),
    ('VIC187H1', 'Prosperity, Justice, and Sustainability: Introduction to Public Policy', '24S', 'This course introduces policy applications of measurement tools and economic concepts by analyzing current issues in the news, such as public spending and debt, health care, social security, energy, climate change, innovation, and education. Concepts from the philosophy and history of economic thought will be used to address such questions as: What is the nature of economic explanations? Do they tell us the truth about reality? Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC188H1', 'Corporate Citizenship, Sustainability, and Ethics', '24S', 'Drawing together philosophical background readings with contemporary applications, this course addresses issues of corporate social responsibility, business ethics, human rights, diversity, and equity, and considers how these topics intersect with a wide range of global practices. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('VIC189H1', 'The Art and Literature of Leadership 2', '24S', 'What is a leader? Are leaders born or are they made, and if they are made is there a craft to being able to lead others? Through works of art, film, and literature, this course examines the various types of men and women who become leaders from natural-born talents to statesmen and state-crafters and individual entrepreneurs with the purpose of defining those qualities that make for the leaders of tomorrow. Restricted to first-year students. Not eligible for CR/NCR option.', 'VIC186Y1', 1, null::jsonb),
    ('VIC190Y1', 'The Arts and Society', '48S', 'The artist, filmmaker, poet or dramatist has changed society and how we imagine our future. The course explores a number of paradigm cases of how the arts have interacted with social problems. Both historical and current examples of the role of the imaginative arts will be explored. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC191Y1', 'Artistic Creation and Public Issues', '72S', 'This course addresses social issues through the exploration of creative activity and the imaginative arts. Topics will be discussed from historical, ethical and philosophical perspectives, and might be considered either in a group or individually. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('VIC196H1', 'Renaissance Queens', '24S', 'This course examines Renaissance queens and queenship by exploring historical and fictional queens and empresses. Topics may include the varied roles queens played within their societies, their relationship with religious and political institutions, the ways in which they negotiated sovereignty vis-a-vis the gender they embodied, and all the ways in which queens were celebrated, criticized, and imagined by artists, writers, and communities of their time and today. Discussion will delve into broad questions around identity and politics and feature a broad range of case studies from Europe to colonial America and beyond. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC197H1', 'Detective Fiction', '24L', 'This course considers detective fiction from its inception in the late nineteenth century to the present day. Students will be introduced to canonical and lesser known authors of detective fiction, evolving generic conventions, and reception history. Course content may include mystery stories, connections to emerging legal processes, and critical writing on detective fiction. Restricted to first-year students. Not eligible for CR/NCR option.', 'ITA197H1', 3, null::jsonb),
    ('VIC198H1', 'Posters and Propaganda', '24L', 'How and when have political posters been used? What forms do they take? How have they changed over time? What can these visual artifacts tell us about the relationship between art and propaganda, and about the political movements that have mobilized visual strategies to advance their aims? This course involves visits to several poster collections, develops visual literacy skills, and highlights the role of the visual in societies past and present. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('VIC199H1', 'The Secret Life of Objects: Analyzing the Culture of Things', '24S', 'This course will examine the materiality of objects with a view to understanding how artefacts are made, their circulation, consumption, and the importance of things to social and cultural life. An investigation of artefacts from various collections in and around the university will be undertaken to develop basic methods for the study, description and analysis of material culture. In addition to hands-on exploration of objects, topics may include antiquarians and their methods, material culture in colonial contexts, and materials in contemporary user-friendly design. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('VIC206H1', 'Psychology and Society', '24S', 'This course explores central developments and ongoing controversies in the scientific study of the human mind, brain and behaviour. It examines topics such as: psychoanalysis, behaviourism, humanistic psychology, evolutionary psychology, intelligence testing, and feminist perspectives. Goals include understanding the historical evolution and social relevance of scientific psychology.', 'VIC106H1', 2, null::jsonb),
    ('VIC207H1', 'Genetic Technologies: Scientific Promises and Ethical Dilemmas', '24L/12T', 'This course examines the ethical dilemmas raised by new genetic technologies. It explores the scientific possibilities they open as well as the moral questions they raise. The topics covered might include: Eugenics, the human genome project, behavioral genetics, genetics and race, genetic screening, gene editing and therapy, gene doping in sports, animal and human cloning, and genetic enhancement.', null, 3, null::jsonb),
    ('VIC245H1', 'Science Wars: Society and the Limits of Scientific Knowledge', '24L', 'An introduction to competing conceptions of scientific knowledge and the role of sociocultural factors in shaping scientific methods, theories, and evidence. Can science provide objective knowledge of the external mind-independent world, or are the empirical aspirations of science limited by the social, cultural, economic, political, and religious contexts that shape “science” itself? Can scientific knowledge reach certainty? How do sociocultural factors affect the process of theory acceptance? This course considers “science” as an epistemological battleground from 17th century debates on inductive reasoning to contemporary arguments about “alternative” science.', null, 2, null::jsonb),
    ('VIC246H1', 'Animal, Vegetable, Mineral, Monster', '24L', 'This course introduces students to the history of natural history--or how thinkers (often called "naturalists") made sense of the world around them. Course readings, lectures, and activities will explore changing perspectives on nonhuman nature across time, from medieval bestiaries to early modern cabinets of curiosities, from colonial botany to more recent legends of Yetis, Bigfoots, and other fantastical creatures of cryptozoology.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('VIC248H1', 'Genetics in the Movies: Mad Scientists, Clones, Superhumans, and Designer Babies', '24L/12T', 'This course explores how scientific and technological advances in genetics have been presented in the movies, focusing on American cinema. We will consider how selected films have influenced social perceptions of the role of scientists and genetic technologies in various areas. The movies and topics covered might include: The Black Stork (1917), A Bill of Divorcement (1932), Tomorrow''s Children (1934) for eugenics; The Boys from Brazil (1978), and Blueprint (2003) for human cloning; Jurassic Park (1993) for de-extinction or bringing extinct animal species back to life; Blade Runner (1982) for synthetic biology and human nature; Gattaca (1997) for human genetic enhancement; The Fly (1958) and The Island of Dr. Moreau (1996) for chimeras; My Sister''s Keeper (2009) for savior siblings; and Okja (2017) for genetically modified animals. We will also analyze the role of documentaries, such as Human Nature (2019) and Make People Better (2022).', null, 3, null::jsonb),
    ('VIC259H1', 'Special Topics Seminar', '24S', 'Topics vary from year to year depending on the instructor. Please see the Victoria College website for specific details about this year''s offerings: https://vic.utoronto.ca/academic-programs/special-topics-courses/vic259h', null, null, '{"operator": "AND", "items": [{"credits": 5.0, "department": null}]}'::jsonb),
    ('VIC259Y1', 'Special Topics Seminar', '48S', 'Topics vary from year to year depending on the instructor. Please refer to the Victoria College website for more information: https://vic.utoronto.ca/academic-programs/special-topics-courses/vic259y', null, null, '{"operator": "AND", "items": [{"credits": 5.0, "department": null}]}'::jsonb),
    ('VIC274H1', 'Wisdom of the Social Sciences', '24S', 'This course examines influential efforts to study human beings and society scientifically, from the seventeenth century to the present. We consider major contributions from prominent thinkers, such as Thomas Hobbes, Adam Smith, Karl Marx, and Sigmund Freud. We also review the contemporary relevance and persistent controversies about their ideas.', null, 2, null::jsonb),
    ('VIC296H1', 'Internship Opportunity', null, 'A practical or experiential learning opportunity under the supervision of a faculty member.', null, null, '{"operator": "AND", "items": [{"credits": 5.0, "department": null}]}'::jsonb),
    ('VIC296Y1', 'Internship Opportunity', null, 'A practical or experiential learning opportunity under the supervision of a faculty member.', null, null, '{"operator": "AND", "items": [{"credits": 5.0, "department": null}]}'::jsonb),
    ('VIC299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('VIC299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('VIC301H1', 'Public Communication in Science', '24S', 'How can scientific findings be efficiently communicated to broader audiences? This course will focus on the methodologies of effective science communication by analyzing the range of available tools, principles, formats, and media. It will introduce students to various techniques of communicating scientific findings to non-specialist audiences by means of social media posts, videos, podcasts, comics, interviews, news briefs, and public speaking. Students will analyze the public''s perception of science and will discuss ways to address the concerns of science skeptics. Students will have the opportunity to create various forms of science communications material.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('VIC302H1', 'Science Policy', '24S', 'The course focuses on the impact of policy on science and the development and implementation of science-related policy. Topics include science funding and allocation of resources, policies concerning the technological application of scientific discoveries, commercialization of science, and the factors that shape the choice of science-based policies in such areas as healthcare, urban planning, weapons development, or environmental monitoring. The course will consider various science policy frameworks that define the power relationships between the stakeholders: government science policymakers, research and educational institutions, private firms, social media, and NGOs.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('VIC359H1', 'Special Topics Seminar', '24S', 'An upper level course. Topics vary from year to year depending on the instructor. Please refer to the Victoria College website for more information: https://vic.utoronto.ca/academic-programs/special-topics-courses/vic359h', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('VIC359Y1', 'Special Topics Seminar', '48S', 'An upper level course. Topics vary from year to year depending on the instructor.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('VIC377H1', 'Special Topics in Science, Technology and Society', '24S', 'In-depth study of a topic related to science and society. Content varies with instructor. Please see the Victoria College website for more information: https://vic.utoronto.ca/academic-programs/special-topics-courses/vic377h', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('VIC390H1', 'Victoria College Independent Studies', null, 'These courses provide an opportunity to design an interdisciplinary course of study not otherwise available within the Faculty. Written application (detailed proposal, reading list and a letter of support from a Victoria College faculty member who is prepared to supervise) must be submitted for approval on behalf of Victoria College. For application procedures visit the Victoria College website. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('VIC390Y0', 'Victoria College Independent Studies', null, 'These courses provide an opportunity to design an interdisciplinary course of study not otherwise available within the Faculty. Written application (detailed proposal, reading list and a letter of support from a Victoria College faculty member who is prepared to supervise) must be submitted for approval on behalf of Victoria College. For application procedures visit the Victoria College website. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
