    ('VIC396H0', 'International Internship Opportunity', '4L/75P', 'This course provides an opportunity to apply acquired knowledge in a practical or experiential placement in an international setting. A faculty supervisor assesses and assigns the necessary written component associated with the internship. The number of weekly hours spent in the placement, the scope of learning objectives, and the nature of reflective and written activities are determined in consultation with the host institution and the supervisor. This is a pass/fail course.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('VIC397H0', 'International Study', null, 'Course content, travel destination, etc., will depend on the instructor. Topics will vary from year to year. Course not offered every year. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('VIC399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('VIC399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('VIC435H1', 'Capstone Seminar: Community-Engaged Research', '12L/78P', 'This course provides students with an experiential learning opportunity in community-engaged research combined with critical reflection and academic discussion within a seminar setting. Through a placement in social enterprise organizations, students develop research-based approaches to support their organization in assessing needs, impact, and resources. Alongside this hands-on experience, interdisciplinary seminar discussions will help students understand how research methodologies, standards, and protocols are deployed in community settings. Not eligible for CR/NCR option.', 'NEW497Y1/ NEW498H1', 3, '{"operator": "AND", "items": [{"credits": 15.0, "department": null}]}'::jsonb),
    ('VIC451H1', 'Capstone: Learning Communities and Higher Education', '24S', 'This course examines higher education in Canada using Victoria University and Victoria''s affiliates as a case study. Topics covered include learning communities, mentoring, experiential learning, and international contexts of education. Students gain practical mentorship experience through placement in first-year Victoria College courses. Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": [{"credits": 15.0, "department": null}]}'::jsonb),
    ('VIC452H1', 'Science, Technology, & Society Internship', '24S', 'This seminar provides academic support for individual work placements in science and technology policy, governance, funding, popularization, advocacy, journalism, or a closely related field in a professional setting, through interdisciplinary readings, integrative discussion, and critical reflection on the culture of labour and the acquisition of workplace skills and experience. Assignments will include reflective exercises and critical analyses, leading to participation in a capstone seminar. This is a Pass/Fail course. Not eligible for CR/NCR option. For internship projects and the link to the application form, visit https://uoft.me/stshpsinternship.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('VIC459H1', 'Special Topics Seminar', '24S', 'Topics vary from year to year. Please see the Victoria College website for more information: https://vic.utoronto.ca/academic-programs/special-topics-courses/vic459h', null, 1, '{"operator": "AND", "items": [{"credits": 15.0, "department": null}]}'::jsonb),
    ('VIC459Y1', 'Special Topics Seminar', '48S', 'Topics vary from year to year. Please see the Victoria College website for more information: https://vic.utoronto.ca/academic-programs/special-topics-courses/vic459y', null, 2, '{"operator": "AND", "items": [{"credits": 15.0, "department": null}]}'::jsonb),
    ('VIC476H1', 'Capstone Seminar in Foreign Policy', null, 'The seminar involves a critical assessment of current foreign policy issues and contemporary world problems. Issues and case studies to be analyzed include: 1. International military interventions to respond to imminent threats or humanitarian crises, issues of legitimacy and effectiveness. e.g., Iraq, Afghanistan, Kosovo, Haiti. 2. Canada-US relations in international crisis management, the track record and the way ahead. 3. Globalization, international terrorism, and their effects on sovereignty, diplomacy and international institutions.', 'POL470Y1', 3, '{"operator": "AND", "items": [{"credits": 15.0, "department": null}, "VIC181H1"]}'::jsonb),
    ('VIC490H1', 'Victoria College Independent Studies', null, 'These courses provide an opportunity to design an interdisciplinary course of study not otherwise available within the Faculty. Written application (detailed proposal, reading list and a letter of support from a Victoria College faculty member who is prepared to supervise) must be submitted for approval on behalf of Victoria College. For application procedures visit the Victoria College website. Not eligible for CR/NCR option.', null, null, null::jsonb),
