    ('WGS160Y1', 'Introduction to Women and Gender Studies', '48L/24T', 'An integrated and historical approach to social relations of gender, race, class, sexuality and disability, particularly as they relate to women''s lives and struggles across different locales, including Canada.', null, 2, null::jsonb),
    ('WGS260H1', 'Texts, Theories, Histories', '24L/12T', 'Examines modes of theories that shaped feminist thought and situates them historically and transnationally so as to emphasize the social conditions and conflicts in which ideas and politics arise, change and circulate.', 'WGS262H1/ WGS262Y1', 2, null::jsonb),
    ('WGS271Y1', 'Gender in Popular Culture', '48L', 'A critical examination of institutions, representations and practices associated with contemporary popular culture, mass-produced, local and alternative.', 'WGS271H1', 1, null::jsonb),
    ('WGS273H1', 'Gender & Environmental (In)Justice', '48L/24T', 'Using a transnational, feminist framework, this course examines material and conceptual interrelations between gendered human and non-human nature, ecological crises, political economies and environmental movements in a variety of geographical, historical and cultural contexts. Does environmental justice include social justice, or are they in conflict? What might environmental justice and activism involve?', 'WGS273Y1', 3, null::jsonb),
    ('WGS275H1', 'Men and Masculinities', '24L/12T', 'Examines how masculinities shape the lives of men, women, transgender people. Effects of construction, reproduction and impact of masculinities on institutions such as education, work, religion, sports, family, medicine, military and the media are explored. Provides critical analysis of how masculinities shape individual lives, groups, organizations and social movements.', null, 2, null::jsonb),
    ('WGS280H1', 'Special Topics in Women and Gender Studies', '24L', 'Subjects will vary from year to year.', null, 2, null::jsonb),
    ('WGS281H1', 'Special Topics in Women and Gender Studies', '24L', 'Subjects vary from year to year.', null, 2, null::jsonb),
    ('WGS331H1', 'Special Topic in Women and Gender Studies', '24L', 'An upper level seminar.  Subjects of study vary from year to year.', null, 1, null::jsonb),
    ('WGS332H1', 'Special Topic in Women and Gender Studies', '24L', 'An upper level seminar.  Subjects of study vary from year to year.', null, 1, null::jsonb),
    ('WGS333H1', 'Special Topic in Women and Gender Studies', '24L', 'An upper level seminar.  Subjects of study vary from year to year.', null, 1, null::jsonb),
    ('WGS334H1', 'Special Topic in Women and Gender Studies', null, 'An upper level seminar. Subjects of study vary from year to year. Please consult the Women & Gender Studies Institute''s website for more information.', null, 1, null::jsonb),
    ('WGS335H1', 'Special Topic in Women and Gender Studies', null, 'An upper level seminar. Subjects of study vary from year to year.', null, null, null::jsonb),
    ('WGS336H1', 'Selected Topics in Cultural Studies', '24L', 'An upper level course. Topics vary from year to year. Please consult the Women & Gender Studies Institute''s website for more information.', null, 1, null::jsonb),
    ('WGS340H1', 'Women and Revolution in the Middle East', '24L', 'This course examines the complex and conflictual relations between women and revolutionary struggles and focuses on a number of theoretical and empirical issues relevant to the Middle East and North Africa context.', 'WGS335H1 Women and Revolution in the Middle East', 3, null::jsonb),
    ('WGS355H1', 'Gendered Labour Around the World', '24L', 'This course will focus on masculinities and femininities in workplace settings, with an emphasis on service work around the world. We will discuss workers'' lived experiences of gender regimes which are embedded within the dynamics of class, race and nation.  The relationships between gender processes and workplace hierarchies will be explored.', 'WGS363H1 Gendered Labour Around the World', 3, null::jsonb),
    ('WGS360H1', 'Making Knowledge in a World that Matters', '24L/12T', 'Teaches skills in feminist approaches to making knowledge.  Introduces feminist practices for doing research and navigating the politics of production and exchange.  Develops skills for conveying knowledge to the wider world, such as through research papers, reports, performance, new media, art.', null, 1, '{"operator": "OR", "items": ["WGS160Y1"]}'::jsonb),
    ('WGS362H1', 'Selected Topics in Gender and History', '24S', 'An upper level seminar. Subjects of study vary from year to year.', null, null, null::jsonb),
    ('WGS363H1', 'Selected Topics in Gender and Theory', '24S', 'An upper level seminar. Subjects of study vary from year to year.', null, null, null::jsonb),
    ('WGS365H1', 'Gender Issues in the Law', '24L', 'Examines the operation of the law as it affects women, the construction and representation of women within the legal system, and the scope for feminist and intersectional analyses of law. Includes an analysis of specific legal issues such as sexuality and reproduction, equality, employment, violence and immigration.', null, 3, null::jsonb),
    ('WGS367H1', 'The Politics of Gender and Health', '24L/12T', 'Examines diverse traditions and normative models of health (e.g. biomedicine, social constructionist, indigenous health) in conjunction with analyses of the origin, politics, and theoretical perspectives of contemporary Women''s Health Movements. Topics may include fertility, sexuality, poverty, violence, labour, aging, (dis)ability, and health care provision.', null, 3, null::jsonb),
    ('WGS369H1', 'Studies in Post-Colonialism', '24L', 'Examines gendered representations of race, ethnicity, class, sexuality and disability in a variety of colonial, neo-colonial, and post-colonial contexts. Topics may include the emergence of racialist, feminist, liberatory and neoconservative discourses as inscribed in literary texts, historical documents, cultural artifacts and mass media.', 'NEW369H1', 1, null::jsonb),
    ('WGS370H1', 'Utopian Visions, Activist Realities', '24L', 'Drawing on diversely situated case-studies, this course focuses on the ideals that inform struggles for social justice, and the mechanisms activists have employed to produce the change. Foci include the gendered implications of movement participation, local and transnational coalition, alternative community formation, and encounters with the state and inter/supra/transnational organizations.', null, 3, null::jsonb),
    ('WGS372H1', 'Women and Psychology/ Psychoanalysis', '24L', 'An interdisciplinary analysis of the relationship of women to a variety of psychological and psychoanalytical theories and practices. Topics may include women and the psychological establishment; women''s mental health issues; feminist approaches to psychoanalysis.', null, 2, null::jsonb),
    ('WGS373H1', 'Gender and Violence', '24L', 'An interdisciplinary study of gendered violence in both historical and contemporary contexts including topics such as textual and visual representations; legal and theoretical analyses; structural violence; war and militarization; sexual violence; and resistance and community mobilization.', null, 3, null::jsonb),
    ('WGS374H1', 'Feminist Studies in Sexuality', '24L', 'Sexual agency as understood and enacted by women in diverse cultural and historical contexts. An exploration of the ways in which women have theorized and experienced sexual expectations, practices and identities.  This course will be offered every three years.', null, 2, null::jsonb),
    ('WGS376H1', 'Studies in Queer and Trans', '24L', 'Takes up conversations in queer and trans studies as separate and entangled fields. It explores how queer and trans people have experienced and theorized gender and sexuality.', 'WGS272H1/ WGS272Y1', 1, null::jsonb),
    ('WGS380H1', 'Feminist Graphic Novels', '24L', 'Comics aren''t new, and graphic novels aren''t either, but feminists have built a rich array of stories about consciousness, resistance, and coming of age in this genre that warrant scholarly attention. In this case, we will read graphic novels for their subtleties, thinking about what picture and text make possible in the exploration of emotion, interconnection, and identity. Reading about resistance to marriage in Aya of Yop City, a child''s view of revolution in Persepolis, parent child reckoning in Fun Home, and loneliness in Skim will advance students'' understandings of the of the power of narrative and the pictorial displacement of innocence.', null, 1, '{"operator": "OR", "items": ["WGS160Y1", "WGS271Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS381H1', 'Black Britain: Race, Gender and Entangled Diasporas', '24L', 'An exploration of Black British history and culture, with a particular focus on labour, overlapping migrations, and racial formations following World War II. Topics and themes may include Afro-Asian-Arab politics and transnational solidarities against empire; citizenship and (non)belonging; mobilizations against fascism and state violence; the Black Women''s Movement and Black British Feminisms; the emergence and interventions of Cultural Studies; the Caribbean Artists Movement and Black British cultural productions more generally.', null, 2, null::jsonb),
    ('WGS382H1', 'Translating Sexuality: Queer Migration, Queer Diasporas', '24L', 'This course examines how notions of sexuality travel as people move within and beyond national borders. It investigates how queer and trans migrants pursue different versions of belonging, solidarity, survival, and hope. Participants will study transnational archives (which may include popular culture, new media, film, literature, and performance) as they trace globalization''s effects on racialized, queer, and trans communities. Major topics may include: queer of color critique; queer settler colonialism; transnational and global south sexualities; imperialism and militarism; neoliberalism and homonationalism; humanitarianism and sexual rights; queer and trans social movements; postcolonial intimacies.', 'WGS482H1', 1, null::jsonb),
    ('WGS385H1', 'Gender and Neoliberalism', '24L', 'Reviews major feminist transnational, Marxist and Foucauldian approaches to the study of neoliberalism. Adopts a comparative, historical and global approach to the ways that gender is implicated in state restructuring, changing roles for corporations and non-governmental organizations, changing norms for personhood, sovereignty and citizenship, and changing ideas about time/space.', null, 3, null::jsonb),
    ('WGS386H1', 'Gender and Critical Political Economy', '24L', 'Offers a critical analysis of political economy, its historical and contemporary contentions and the ruptures that open the space for alternative theorizing beyond orthodox and heterodox thinking, by inserting gender and intersecting issues of power, authority and economic valorization across multiple and changing spheres: domestic, market and state.', null, 3, null::jsonb),
    ('WGS390H1', 'Land-ing: Indigenous and Black Futurist Spaces', '24L', 'Students are invited to think through the relationships between Indigenous and Afro-futurist concepts of land. This class will engage Indigenous feminist and Black queer and feminist theories of land and space, linking them to Afrofuturist and Indigenous futurist thought. We explore various texts in relation to emergent methodologies, decolonial desires, and love and radical relationalities.', 'WGS335H1 (Special Topic in Women and Gender Studies: Indigenous Feminist Theory), offered in Fall 2015,  WGS335H1 (Special Topic in Women and Gender Studies: Decolonial Aesthetics and Futurities), offered in Winter 2018, Winter 2019 and Winter 2020', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WGS396H1', 'Writing the Body', '24L', 'Examines the ways in which bodies are lived and inscribed and represented through a variety of genres. Students will work through issues of corporeality and materiality in the production and reception of texts and will practice embodied writing on a personal level through in-class workshops and written assignments.', null, 1, null::jsonb),
    ('WGS397H1', 'The Politics of Girlhood', '24L', 'The course communicates the growing field of "girl studies" and provides a critical exploration of the historical, social, psychological and political definitions attached to girlhood.  We will move toward a feminist understanding of how definitions of girl-child shape individual experience, historical narratives, cultural representations, political agendas and futures.', 'WGS335H1: The Politics of Girlhood', 2, null::jsonb),
    ('WGS420H1', 'Asian/North American Feminist Issues', '24L', 'A transpacific examination of issues that have directly and indirectly shaped the feminist and other related critical inquiries in Asia and among the Asian diasporas in Canada and the United States.', null, 3, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS426H1', 'Gender and Globalization: Transnational Perspectives', '24L', 'Critically examines current interdisciplinary scholarship on globalization, its intersections with gender, power structures, and feminized economies. Related socio-spatial reconfigurations, ''glocal'' convergences, and tensions are explored, with emphasis on feminist counter-narratives and theorizing of globalization, theoretical debates on the meanings and impacts of globalization, and possibilities of resistance, agency, and change.', 'WGS463H1 (Advanced Topics in Gender Theory: Gender and Globalization: Transnational Perspectives), offered in Fall 2009', 3, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS434H1', 'Advanced Topics in Women and Gender Studies', '24S', 'An upper level seminar. Topics vary from year to year depending on instructor. Please consult the Women & Gender Studies Institute''s website for more information.', null, null, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS435H1', 'Advanced Topics in Women and Gender Studies', '24S', 'An upper level seminar. Topics vary from year to year depending on instructor.', null, null, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS436H1', 'Advanced Topics in Women and Gender Studies', '24S', 'An upper level seminar. Topics vary from year to year depending on the instructor.', null, null, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS437H1', 'Advanced Topics in Women and Gender Studies', '24S', 'An upper level seminar. Topics vary from year to year depending on the instructor.', null, null, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS440H1', 'Decolonial Cyborgs for Planetary Futures', '24L', 'Drawing together film, fiction, and theory this course invites students to explore ways of imagining other worlds. From afro-futurism to planetary humanism, from cyborgs to hauntings, from science fiction fantasies to the politics of aliens, the course examines and produces feminist, postcolonial, anti-racist, and queer visions of other worlds.', null, 1, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS442H1', 'Toxic Worlds, Decolonial Futures', '24S', 'This course explores the ways environmental violence is an integral practice of settler colonialism that affects human and non-human life, disrupts Indigenous sovereignty, and enacts ongoing racism. A typical way of addressing environmental violence is to document the harm done to bodies and communities. This class asks, how might we also refuse environmental violence and enact better obligations to land/body relations? What kind of decolonial futures can be summoned in the aftermath of environmental violence? Our readings will bring Indigenous feminist approaches together with Black feminist, queer, and feminist environmental justice approaches. Participants will build upon the readings to create their own decolonial environmental justice future projects.', 'WGS463H1 (Advanced Topics in Gender Theory: Toxic Worlds, Decolonial Futures), offered in Winter 2018, Winter 2019 and Winter 2020', 2, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS450H1', 'Modernity, Freedom, Citizenship: Gender and the Black Diaspora', '24L', 'Explores transnational feminist genealogies of the black diaspora. The course pays attention to the contexts and movements that generated key questions, exploring how these interventions disclose preoccupations with modernity, freedom and citizenship. Topics may include trauma and memory, sexual citizenship, Afrofuturism, indigeneity, and the crafting of political communities.', 'WGS434H1 (Advanced Topics in Women and Gender Studies: Black Diasporic Feminisms: Modernity, Freedom, Citizenship), offered in Fall 2012', 2, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS451H1', 'Independent Study in Women and Gender Studies Issues', null, 'Under supervision, students pursue topics in Women and Gender Studies not currently part of the curriculum. For students in the Women and Gender Studies Specialist or Major. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": ["WGS160Y1", "WGS260H1", "WGS360H1"]}'::jsonb),
    ('WGS451Y1', 'Independent Study in Women and Gender Studies', null, 'Under faculty supervision, students pursue topics in Women and Gender Studies that are not currently part of the curriculum. For students in the Women and Gender Studies Specialist or Major. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": ["WGS160Y1", "WGS260H1", "WGS360H1"]}'::jsonb),
    ('WGS460Y1', 'Honours Seminar', '24S', 'Supervised undergraduate thesis project undertaken in the final year of study. Students attend a bi-weekly seminar to discuss research strategies, analytics, methods and findings. A required course for Specialist students. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS461Y1', 'Advanced Topics in Women and Gender Studies', '48S', 'An upper level seminar. Topics vary from year to year depending on the instructor.', null, null, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS462H1', 'Advanced Topics in Gender and History', '24S', 'An upper-level seminar. Topics vary from year to year depending on instructor.', null, null, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS463H1', 'Advanced Topics in Gender Theory', '24S', 'Senior students may pursue more advanced study in feminist theory. Topics vary from year to year depending on instructor.', null, null, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS465H1', 'Special Topics in Gender and the Law', '24S', 'Senior students may pursue advanced study in gender and law. Topics vary from year to year.', null, 3, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", "WGS365H1", {"credits": 0.5, "department": "WGS"}]}'::jsonb),
    ('WGS470Y1', 'Community Engagement', '48S', 'The application of theoretical study to practical community experience. Advanced Women and Gender Studies students have the opportunity to apply knowledge acquired in the Women and Gender Studies curriculum through a practicum placement within a community organization. Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS480H1', 'Challenging Coloniality: Caribbean Sexualities in Transnational Perspective', '24S', 'This course foregrounds the Caribbean as a transnational space, where sexuality, gender, race and class are intimately connected and shaped by colonial legacies and contemporary circuits of globalization.', 'WGS435H1 (Topics: Challenging Coloniality: Caribbean Sexualities in Transnational Perspective), offered in Summer 2017', 2, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WGS481H1', 'Gender, Sexuality and Black Liberation from Black Power to #BlackLivesMatter', '24S', 'This course maps genealogies of black insurgency and transnational itineraries of intersectional theorizing, organizing, and praxis from the 20th century to our present moment. Through close study of works by and about black revolutionary migrants, exiles, intellectuals, fugitives, and so-called terrorists, participants will critique and create radical visions for emancipation. Major topics and themes may include black feminisms; queer insurgencies; transnational imaginaries and solidarities; silence and intracommunal violence; accountability and transformative justice. Through collective discussion, writing, and reflection we interrogate visions and strategies of emancipation, and imagine radical futures historically and in our own times.', 'WGS435H1 (Topics: Sex, Gender and Revolution from Black Power to #BlackLivesMatter), offered in Winter 2017 and Fall 2017', 2, '{"operator": "AND", "items": [{"credits": 2.5, "department": "WGS"}, "WGS160Y1", {"credits": 1.0, "department": "WGS"}]}'::jsonb),
    ('WRR103H1', 'Introduction to Academic Writing', '36L', 'This course introduces students to the strategies and practices of successful writing at the university and beyond.  WRR103H1 challenges students to reflect on and cultivate their strengths as readers and writers as they enter the university. Students will develop their critical reading abilities and written communication skills through meaningful writing projects in diverse genres, including multimodal composition.', 'INI103H1', 2, null::jsonb),
    ('WRR104H1', 'Writing Reports', '36S', 'Students will learn the fundamentals of report writing, including how to write abstracts and conduct literature reviews as well as qualitative and quantitative research. Students also learn to communicate visually, including how to create tables, charts, and graphs with attention to purpose, audience, structure, style, skills they apply to a formal report and a poster presentation.', 'INI104H1', 2, null::jsonb),
    ('WRR201H1', 'Theories of Rhetoric: A Brief History of Persuasion', '36S', 'When contemporary critics seek to discredit dishonest politicians, they tend to refer to their discourse as “mere rhetoric.” But there is so much more to rhetoric than deception. This course examines the history of rhetoric, the art of persuasion, from its birth in Greco-Roman antiquity to its rebirth in twentieth and twenty-first century thought. In addition to tracking the history of Western ideas about persuasion, we will bring rhetorical theories to bear on vital questions about philosophy, psychology, media, and advertising.', 'INI201H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR211H1', 'Introduction to Creative Writing', '36S', 'This introductory course focuses on the process and craft of creative writing. Students will study short fiction, creative nonfiction and poetry by established writers, and learn to respond to works-in-progress by their peers. A variety of activities will help students generate, develop, and revise a portfolio of original creative work.', 'INI211H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR300H1', 'Strategic Writing in Business and the Professions: Theory and Practice', '36S', 'Students learn the theory and practice of effective and ethical communication in the workplace, including business, government, and non-profit organizations. Students apply ethical reasoning models to case studies. Students have an opportunity to work directly with a community partner, helping them to solve an industry-specific problem or concern. This experiential learning enables students to work together as a team to develop relevant solutions as they strengthen their written and verbal communication skills.', 'INI300H1,  INI302H1,  WRR302H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR302H1', 'Writing in Business and the Professions for Rotman Commerce Students', '24L/12T', 'Designed for and restricted to Rotman Commerce undergraduates, the course reflects the program''s learning goals, which include critical thinking, ethical reasoning, and business and professional communication (oral and written). Students apply business communication theory and ethical reasoning models to business cases. Students have an opportunity to work directly with a community partner, helping them to solve an industry-specific problem or concern. This experiential learning enables students to work together as a team to develop relevant solutions as they strengthen their written and verbal communication skills', 'INI300H1,  INI302H1,  WRR300H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR303H1', 'Digital Rhetoric', '36S', 'This course explores the pivotal role that media plays in our culture. Beginning with U of T rhetorician Marshall McLuhan''s far-reaching ideas about media environments,  WRR303H1 takes students on a journey through a wide variety of ideas about media, technology, and rhetoric. Topics include the rhetorical dimensions of social media platforms, the strengths and shortcomings of online activism, the emergence of surveillance capitalism, and the operation of persuasion in dating apps.', 'INI303H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR305H1', 'Word and Image in Modern Writing', '36S', 'This course examines the persuasive power of writing about visual art and texts. Students will analyze a variety of texts about visual images from several disciplines and genres: journalism, informal essays, poetry, and scholarly writing.', 'INI305H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR306H1', 'Writing About Plants and the Environment', '36S', 'This course uses rhetoric, the study of persuasion, to analyze the cultural, political, and scientific importance of plants. We examine Indigenous knowledge related to plants and the environment as well as debates about plant communication, urban tree coverage and inequality, and environmental justice issues. We also explore the social and health benefits of community gardening, horticultural therapy, and forest bathing. Students reflect on their own relation to land as they deepen their knowledge and appreciation of plants and develop expertise in communicating with public audiences through multimodal writing projects (such as podcasts and video essays) and local field trips.', 'WRR308H1 (Selected Topics in Writing and Rhetoric: Writing About Plants and the Environment) offered in Fall 2023 and Winter 2023.', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR307H1', 'Rhetoric of Health and Medicine', '36S', 'Since its inception, rhetoric has been concerned with persuasion and its relationship to human flourishing. This course brings rhetorical thought into important dialogue with health research, medical practices, and pharmaceutical advertising. Medicalized phenomena—like hypochondria, depression, sexual dysfunction, and death & dying—are all bound up with influence. A rhetorical perspective on health and wellness tracks this influence through networks of individuals, institutions, texts, media forms, genres, and narratives.', 'INI308H1 (Selected Topics in Writing and Rhetoric: Rhetoric of Health and Medicine) offered in Fall 2019, and  WRR308H1 (Selected Topics in Writing and Rhetoric: Rhetoric of Health and Medicine) offered in Winter 2022', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR308H1', 'Selected Topics in Writing and Rhetoric', '24S', 'Courses on selected topics in Writing and Rhetoric.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR309H1', 'Professional Communication with Environmental Groups', '36S', 'Given the climate crisis, how do environmental groups use communication to advance their aims? In this community-engaged learning course, students work with environmental organizations on professional communication projects. Students learn about rhetoric and communication as they refine and reflect on their writing processes and practice writing in multiple genres. Students create a variety of multimodal communication projects such as social media and web content for community partners. Through readings, reflection, discussion, and projects involving feedback from peers, instructor, and community partners, students learn principles and strategies to inform and persuade a variety of audiences about environmental issues.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR310H1', 'Stylistic Editing and Copy Editing', '36S', 'This course introduces students to professional editorial conventions at two later stages of the editorial process. Both stages require analytical skills and sentence expertise. Through stylistic editing, students learn how to improve a writer''s literary style; through copy editing, they learn how to ensure both accuracy and consistency (editorial style).', 'INI310H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR311H1', 'Seminar in Creative Writing – Fiction', '36S', 'This workshop-based course teaches students about the creative writing process and the fundamentals of writing fiction specifically. Through readings of fiction in various genres, discussions, creative writing prompts and longer assignments, students learn how storytellers work with setting, character, scenes, structure, point-of-view, style and other elements. Students will learn how to take creative risks and grow through writing fiction, how to develop solid work from shaky drafts, how to be generous yet shrewd editors of their own and others'' work, and how and why to be active in a writing community.', 'WRR311Y1,  INI311Y1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR312H1', 'Writing Literary Journalism', '36L', 'This course introduces students to works by some of the most influential literary journalists of the twentieth and twenty-first centuries. Classes will be devoted to individual literary-journalistic genres: the personal essay, the profile, the polemic, the memoir, literary reportage, and cultural criticism. Students will look closely at key writers who worked across these genres: George Orwell, James Baldwin, Joan Didion, Joyce Carol Oates. Over the semester, students will develop and write a feature-length work of literary journalism in a genre of their choice, to be refined through peer workshop and instructor feedback.', 'INI308H1 (Selected Topics in Writing and Rhetoric: Writing Literary Journalism), offered in Summer 2021', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR313H1', 'Visual Rhetoric', '36L', 'This course examines how images and objects communicate with and persuade viewers. Visual rhetoric is part of the broader academic field known as rhetorical studies. This course will introduce students to the “language” of display, exploring questions such as the following: How does physical arrangement, context, and architectural space give voice to the silent object? How are fine art and decorative art objects invested with meaning? Students will be introduced to object-based learning and material culture and learn to analyze and interpret visual grammar in international exhibitions, in auction and exhibition catalogues, in reviews of exhibits, and in museum collections. Objects will include ceramics, jewellery, interiors, architecture, and fashion in the eighteenth, nineteenth, and twentieth centuries.', 'INI413H1,  WRR413H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR315H1', 'Writing from Territory: Creative Writing in Fiction and Nonfiction', '36S', 'This course guides students in a creative writing process that is engaged with place and time. Classes are held outdoors at various locations in Toronto. Through guided writing activities, discussions, assignments and writing workshops, students learn how writing grounded in and informed by territory can expand their work, adding intimacy, immediacy, authenticity and depth. Readings and techniques are drawn from literary fiction of different genres (e.g., realism, speculative, YA, fantasy), and a range of creative nonfiction. Students are invited to explore any genre.', 'WRR308H1 (Selected Topics in Writing and Rhetoric: Writing From Territory: Creative Writing in Fiction and Nonfiction) offered in Summer 2023', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR316H1', 'Developmental and Substantive Editing', '36S', 'This course introduces professional editorial conventions at two early stages of the editorial process. Both stages require editors to think critically and creatively as they assess content, organization, and argument. Students learn how to analyze and evaluate these elements, envision possible improvements, and explain these suggestions persuasively.', 'INI316H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR317H1', 'Advanced Academic Writing', '36S', 'The course covers various kinds of academic writing, including the essay, the long form book review, the annotated bibliography, and the undergraduate thesis. Students learn to recognize the rhetorical frames, persuasive strategies, elements of style, and uses of scholarly evidence that are features of academic writing. Readings include academic and non-academic prose from a variety of disciplines. Through reading, research, reflection, writing, and citation of sources, students learn to engage in the scholarly conversation that is foundational to all advanced academic writing. Students will develop voices as writers in dialogue with other writers, scholars, and commentators.', 'WRR203H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR319H1', 'Rhetoric of Race', '36L', 'This course will introduce students to an array of thinkers who scrutinize the history of rhetoric and communication from the standpoints of critical race studies. Over the last decade, scholars working in the field of rhetorical studies have dedicated a great deal of attention to the importance of race to critical interrogations of communication. Black and Indigenous scholars, in particular, have been at the forefront of thinking about communication through the lens of race. From persuasive oratory to recent calls for a rhetoric of sovereignty, the rhetoric of race takes up the intersections of communication, justice, and history. This course provides students with an opportunity to reflect on traditional rhetorical concerns about persuasion and influence in relation to colonialism, systemic racial prejudice, and conceptions of social justice.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('WRR405Y1', 'Independent Studies in Writing and Rhetoric', null, 'Independent research projects devised by students and supervised by the Writing and Rhetoric staff. Open only to students who are completing the Minor Program in Writing and Rhetoric Program. Applications should be submitted to the Program Director by June 1 for a Fall session course or by November 1 for a Spring session course. Not eligible for CR/NCR option.', 'INI405Y1', null, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["WRR103H1", "WRR104H1", "WRR201H1", "WRR203H1", "WRR303H1", "WRR305H1", "WRR413H1", "WRR414H1"]}]}'::jsonb),
    ('WRR406H1', 'Independent Studies in Writing and Rhetoric', null, 'Independent research projects devised by students and supervised by the Writing and Rhetoric staff. Open only to students who are completing the Minor Program in Writing and Rhetoric Program. Applications should be submitted to the Program Director by June 1 for a Fall session course or by November 1 for a Spring session course. Not eligible for CR/NCR option.', 'INI406H1', null, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["WRR103H1", "WRR104H1", "WRR201H1", "WRR203H1", "WRR303H1", "WRR305H1", "WRR413H1", "WRR414H1"]}]}'::jsonb),
